"""Original Turkish cases. Source mappings are internal, never answer-screen references."""
import json, random
from pathlib import Path
ROOT=Path(__file__).parent
TITLE='CISA: Gerçek Bir IT Denetçisi Olabilir misin? 🎯'
DESCRIPTION='Bir şirketin IT denetim ekibine katıldın. Önünde 5 farklı görev alanı, 100 kritik karar ve gerçek iş hayatından senaryolar var. Denetim planlayacak, riskleri değerlendirecek, sistemleri inceleyecek, bulgular yazacak ve krizlerle mücadele edeceksin. Peki gerçekten bir IT Auditor gibi düşünebiliyor musun?'
DOMAINS=['Denetim süreci','IT yönetişimi ve yönetimi','Sistem edinimi, geliştirme ve uygulama','IT operasyonları ve iş sürekliliği','Bilgi varlıklarının korunması']
questions=[]
def add(domain,kind,topic,context,prompt,choices,reason,work,answer=None):
 n=len(questions)+1
 opts=[]
 if kind=='fill_blank':
  answers=choices; rationale={}; correct_text=answers[0]
 else:
  # Each author-specified tuple includes a distinct rationale. Correct position varies.
  opts=[dict(id=f'k{i+1}',text=t,feedback=r) for i,(t,r) in enumerate(choices)]
  answers=answer or ['k1']; rationale={o['id']:o['feedback'] for o in opts}
  random.Random(1300+n).shuffle(opts)
  correct_text='\n'.join((f'{i+1}. ' if kind=='sentence_order' else '• ')+next(o['text'] for o in opts if o['id']==key) for i,key in enumerate(answers))
 difficulty=['beginner']*6+['intermediate']*8+['advanced']*6
 questions.append(dict(external_id=f'cisa-auditor-v1-{n:03}',number=n,domain=domain,kind=kind,topic=topic,prompt=prompt,context=f'Domain {domain} · Görev {(n-1)%20+1}/20\n\n'+context,options=opts,answer=answers,explanation='🧠 Neden doğru?\n'+reason+'\n\n💼 Gerçek iş hayatında\n'+work,hint='Kararını bu vakadaki iş etkisi ve eldeki kanıtla karşılaştır.',difficulty=difficulty[(n-1)%20],goals=[topic],base_xp=10,premium=False,published=True,order=n,card_pages=[]))
def decision(d,k,t,c,p,a,b,e,f,r,w):
 add(d,k,t,c,p,[a,b,e,f],r,w)
def order(d,t,c,steps,r,w):
 add(d,'sentence_order',t,c,'İşlem kartlarını bu vaka için doğru sıraya koy.',[(s,'Bu adımın yeri önceki adımın çıktısına bağlıdır.') for s in steps],r,w,[f'k{i+1}' for i in range(len(steps))])
def multi(d,t,c,p,items,r,w,correct=('k1','k2')):
 add(d,'multi_select',t,c,p,items,r,w,list(correct))
def fill(d,t,c,p,answers,r,w):add(d,'fill_blank',t,c,p,answers,r,w)
# DOMAIN 1 — Your first engagement, from authority to follow-up.
decision(1,'choice','Bağımsız kanıt','İlk sabahın, Kıyı Bankası. Murat (IT Müdürü), sertifikayı masaya koyuyor: “Geçen yıl denetlendik. Yeniden test zaman kaybı.” Bu yıl ödeme uygulaması değişmiş. Selin (Denetim Yöneticin) senden ilk yaklaşımını istiyor.','En uygun yanıtın hangisi?',('Güncel riskleri belirleyip ilgili kontrolleri kanıtla test etmek','Sertifika geçmiş incelemeyi gösterir; değişen sistem için güncel kanıt gerekir.'),('Sertifikanın kapsamını okuyup bu yıl test yapmamak','Kapsamı okumak yararlıdır; bu yılki uygulamayı tek başına doğrulamaz.'),('Geçmiş rapordaki bulguları aynen yeni rapora taşımak','Geçmiş bulgu yeni dönemin koşullarını ve uygulamasını kanıtlamaz.'),('Müdürün beyanını alıp düşük riskli alanlarla başlamak','Beyan, ödeme sisteminin değişen riskini öncelik dışına çıkarmaya yetmez.'),'Denetim, güvenilir görünen beyanı bile risk ve dönemle uyumlu kanıtla sınar. Sertifika bir başlangıç bilgisi olabilir; kontrolün bugün çalıştığını göstermez.','Sertifikayı küçümsemeden kapsamını öğren; değişiklik kayıtları ve bağımsız testlerle kendi sonucunu kur.')
multi(1,'Denetim yetkisi','Kıyı Bankası log erişimini reddediyor. Denetim yönergesi sana yetki veriyor; ancak sadece denetim amacıyla gerekli veriye erişebilirsin.',['Yetkiyi kullanırken hangi iki yaklaşım doğru?'][0],[('Yönergedeki erişim yetkisini ilgili yöneticiyle netleştirmek','Görevin yetki dayanağını görünür kılar.'),('Gereken alanları ve güvenli aktarım yöntemini tanımlamak','Veri erişimini denetim amacıyla sınırlar.'),('Tam müşteri verisini kişisel e-posta hesabına istemek','Amaçla orantısız toplama ve güvensiz aktarım yaratır.'),('Sisteme bir çalışan parolasıyla gizlice erişmek','Yetki kişisel hesap kullanımını ve iz bırakmayı gerektirir.')],'Yönerge erişimin dayanağıdır; veri minimizasyonu ve güvenli işleme bu yetkinin sınırlarıdır. Erişim anlaşmazlığı çözülemezse kapsam kısıtını yöneticine bildir.','PBC talebine veri alanlarını, dönemi, saklama süresini ve aktarım kanalını yaz.')
order(1,'Riske dayalı plan','Ödeme denetiminin amacı bellidir: yetkisiz işlemleri önleyen kontrolleri değerlendirmek. Planı henüz onaylamadın. Önce iş akışını anlaman gerekiyor.',['Ödeme akışını ve sistem bağımlılıklarını öğren','Akıştaki önemli riskleri değerlendir','Risklere göre kapsamı ve testleri belirle','Planı yetkili denetim yöneticisine onaylat'],'Testler, tanımlanan riskin kontrolünü ölçmelidir. Akışı bilmeden kapsamı çizmek kritik bağımlılıkları dışarıda bırakabilir. Onay, bu hazırlığın ardından gelir.','Planına sadece sistem adlarını değil, hangi risk hakkında hangi kanıtla sonuç vereceğini yaz.')
decision(1,'drag_select','Risk önceliği','İki günlük ek test süren var. Dört alanın etkisi ve mevcut güvencesi masada. En önemli açık riski seç.','Önce hangi alanı incelersin?',('Ödeme yetki kontrolü; yeni sürüm çıktı, test kanıtı yok','Müşteri parası etkilenebilir ve yeni sürüm için güvence eksiktir.'),('İntranet teması; renkler değişti, onay kaydı eksik','Onay eksikliği önemlidir ancak verilen etki daha düşüktür.'),('Arşiv taraması; erişim kapalı, geçen hafta test edildi','Riskin güncel kontrol kanıtı bulunuyor.'),('Eğitim portalı; gecikme oldu, manuel süreç çalışıyor','İş etkisi sınırlı ve alternatif süreç mevcut.'),'Öncelik, yalnızca eksik belge sayısıyla belirlenmez. İş etkisi, değişim ve kanıt eksikliği birlikte ödeme kontrolünü öne çıkarır.','Kaynak kısıtında neden bazı alanları önce test ettiğini çalışma kâğıdında açıkla.')
fill(1,'Kontrol testi','Bir ödeme kaydını kaynağına kadar izledin. Şimdi farklı bir testte, 40 ödeme için gerekli çift onayın gerçekten uygulanıp uygulanmadığını inceliyorsun.','Bu ikinci çalışma hangi testtir? “___ testi” olarak yaz.',['kontrol','kontrol testi','uygunluk','uygunluk testi'],'Kontrol testi, tanımlı kontrolün işletilip işletilmediğini değerlendirir. İşlem tutarının gerçekliğini doğrulamak ise başka bir test amacıdır. Aynı veri farklı amaçlarla incelenebilir.','Örneklem dosyasında test amacını yaz; doğruladığın şeyi olduğundan geniş sunma.')
decision(1,'scenario','Çıkar çatışması','Selin (Denetim Yöneticin) seni Atlas Belediyesinin satın alma denetimine atıyor. Geçen ay bu sürecin erişim kontrolünü danışman olarak sen tasarladın. Ekip takvimi çok sıkışık.','İlk yapman gereken nedir?',('Önceki görevini bildirip bağımsız değerlendirme istemek','Kendi tasarımını değerlendirme tehdidini atama öncesinde görünür kılar.'),('Kontrolü iyi bildiğin için testleri tek başına üstlenmek','Teknik bilgi, kendi çalışmanı değerlendirme riskini ortadan kaldırmaz.'),('Sadece olumlu sonuçları başka denetçiye kontrol ettirmek','Seçici ikinci inceleme, kapsamlı bağımsızlık önlemi değildir.'),('Çatışmayı rapor bittikten sonra ek notla açıklamak','Tehdidin etkisi çalışma yapılmadan ele alınmalıdır.'),'Bağımsızlık yalnızca dürüst olmak değildir; kendi kararlarını değerlendirme tehdidini de yönetmektir. Atama, gözetim veya bağımsız inceleme önlemini denetim yönetimi belirler.','Uzmanlığını paylaşabilirsin; fakat bağımsız güvence sorumluluğunu tek başına üstlenme.')
decision(1,'choice','Kanıt güvenilirliği','Atlas Belediyesinde kullanıcı yetkileri için üç farklı dosya geldi. IT Müdürü imzalı bir liste gönderdi; sistem çıktısı da var, fakat hangi tarihte alındığı bilinmiyor.','Sonuç vermeden önce en uygun adım nedir?',('Çıktının kaynağını, dönemini ve tamlığını doğrulamak','Doğru evren ve dönem bilinmeden listeden güvenilir sonuç çıkarılamaz.'),('İmzalı listeyi yeterli sayıp sistem çıktısını bırakmak','İmza sorumluluk gösterir; sistemdeki tüm yetkilerin listelendiğini kanıtlamaz.'),('En uzun dosyayı seçip daha büyük örneklem almak','Daha büyük örneklem hatalı evreni düzeltmez.'),('İki dosyada ortak olan kullanıcıları test etmek','Ortak kayıtlarla sınırlanmak dışarıda kalanları sistematik olarak atlar.'),'Kanıtın kalitesi; kaynağına, ilgili döneme ve tamlığına bağlıdır. Önce bu özellikleri doğrula, sonra örneklem ve test sonucunu değerlendir.','Dosyanın sorgusunu, alınma zamanını ve kaynak sistem toplamını kayıt altına al.')
order(1,'Örneklem hazırlığı','Belediyede yıl boyunca 1.240 satın alma değişikliği var. Amacın normal değişikliklerde bağımsız onayın uygulanmasını test etmek. Acil değişiklikler ayrı test edilecek.',['Evrenin dönemini ve normal değişiklik ölçütünü tanımla','Filtrelenen listenin tamlığını kaynakla doğrula','Amaç ve riske uygun örneklem yöntemini seç','Seçilen kayıtlarda bağımsız onayı test et'],'Örneklemi güvenilir kılan ilk şey büyük olması değil, doğru evrenden seçilmesidir. Acil ve normal akışlar ayrıldığı için seçim ölçütü baştan sabit olmalıdır.','Evren, hariç tutmalar ve seçim yöntemi başka bir denetçinin aynı çalışmayı izlemesini sağlamalı.')
decision(1,'drag_select','Analitik istisna','Satın alma sorgunda dört sonuç var. Ölçüt: Bir kişi hem tedarikçi hesabını değiştirmiş hem aynı hesaba ödemeyi onaylamışsa incele.','Hangi kayıt doğrudan bu ölçüte uyuyor?',('U17: hesabı değiştiren U17, ödeme onaylayan U17','Aynı kimlik iki çelişen işlemi gerçekleştirmiştir.'),('U18: hesabı değiştiren U18, ödeme onaylayan U19','İki farklı kimlik var; tanımlı ölçüt karşılanmıyor.'),('U20: yalnız ödeme onayı var, hesap değişikliği yok','Çift görev göstergesi bulunmuyor.'),('U21: hesap değişti, ödeme henüz yapılmadı','Hesap değişikliği tek başına tanımlı istisna değildir.'),'Analitik istisna, inceleme için bir sinyaldir; otomatik olarak sahtekârlık kanıtı değildir. U17 için rol, zaman ve gerekçe kanıtlarını derinleştir.','Önce ölçütü tutarlı uygula; sonra istisnanın neyi kanıtlayıp neyi kanıtlamadığını ayır.')
decision(1,'scenario','İstisna değerlendirme','U17 hesabı ortak kullanılan bir servis hesabı olabilir. Dört işlemde aynı kimlik görünüyor. Zeynep (Finans Müdürü), “Kesin usulsüzlük yazabilirsiniz” diyor.','En uygun kararın nedir?',('İşlem sahipliğini araştırıp kontrol zayıflığını kanıtla ayırmak','Ortak hesap, kimliği belirsiz kılar; sahtekârlık iddiası için ek kanıt gerekir.'),('Dört kaydı doğrudan sahtekârlık olarak raporlamak','İstisna sayısı niyeti ve gerçek işlem sahibini kanıtlamaz.'),('Servis hesabı ihtimali nedeniyle istisnaları kapatmak','Belirsizlik, izlenebilirlik riskini ortadan kaldırmaz.'),('Yöneticinin yazılı beyanını tek başına esas almak','Beyan bağımsız işlem kanıtının yerini tutmaz.'),'Denetçi olguyu, çıkarımı ve doğrulanmamış iddiayı ayırır. Aynı kimlik çakışması somut bir bulgudur; kişinin niyeti henüz bilinmiyor.','Gerekirse uygun soruşturma kanalına yönlendir; kendi kanıtının sınırını raporda koru.')
decision(1,'choice','Denetim riski','Örnekleminde onay eksikliği görmedin. Deniz (Kıdemli Denetçi), “Sıfır istisna, sıfır risk demektir” diye not düşüyor.','Bu not doğru mu?',('Yanlış; örneklem tüm evrendeki hataları dışlamaz','Örnekleme ve diğer denetim riskleri devam edebilir.'),('Doğru; tüm örnekler uygun olduğu için risk yoktur','Sonucu test edilmemiş evrene kesinlik olarak genişletir.'),('Doğru; sistemde otomatik onay varsa risk yoktur','Otomasyonun tasarımı ve işletimi de başarısız olabilir.'),('Yanlış; örneklem hiçbir güvence sağlayamaz','Uygun tasarlanmış örneklem makul güvence sağlayabilir.'),'Sıfır istisna olumlu bir test sonucudur; mutlak güvence değildir. Kullanılan yöntem, örnek büyüklüğü ve kontrol koşulları sonuç üzerinde etkilidir.','“Test edilen örneklerde istisna görülmedi” ifadesi, “hiç hata yok” ifadesinden daha doğru bir sınır çizer.')
multi(1,'Çalışma kâğıdı','Mavi Hastanede rapor incelemesine geçtin. Bağımsız ikinci denetçi, erişim testini tekrar izleyebilmek istiyor.','Hangi iki kayıt bu amaca doğrudan hizmet eder?',[('Evren, seçilen kayıtlar ve uygulanan test adımları','Testin nasıl yapıldığını izlenebilir kılar.'),('Kanıt bağlantıları ve sonuca ulaşma gerekçesi','Bulguyla kanıt arasında yeniden incelenebilir bağ kurar.'),('Denetçinin hastane hakkında kişisel izlenimleri','Kişisel izlenim testin tekrar izlenmesini sağlamaz.'),('Çalışanların gereksiz özel iletişim bilgileri','Denetim amacı dışı veri kayıt kalitesini artırmaz.')],'Çalışma kâğıdı, neyi neden test ettiğini ve hangi kanıtla hangi sonuca ulaştığını göstermelidir. Gereksiz kişisel veri eklemek kalite değildir.','Dosyayı senden sonra devralan kişi, sözlü açıklamana ihtiyaç duymadan temel değerlendirmeyi izleyebilmeli.')
order(1,'Çelişkili kanıt','Hastanede yönetici “hesap aynı gün kapandı” diyor. HR listesi ayrılış tarihini, erişim kaydı ise ertesi gün oturum açıldığını gösteriyor. Zaman dilimleri henüz doğrulanmadı.',['Kaynakların kimlik ve zaman dilimlerini doğrula','Ayrılış ve erişim kayıtlarını aynı zaman çizelgesinde karşılaştır','Çelişkiyi sorumlu yöneticiyle kanıt üzerinden görüş','Doğrulanan durumu ve kalan belirsizliği belgele'],'Önce farklı saat ve kimlik gösterimlerinin aynı olayı temsil ettiğini doğrula. Ardından görüşme, gözlenen çelişkinin nedenini anlamaya hizmet eder.','Uyuşmazlığı kişisel tartışmaya çevirmeden aynı zaman çizelgesi üzerinden konuş.')
decision(1,'drag_select','Önemlilik','Hastanenin kapanış toplantısına tek önemli bulgu taşıyacaksın. İş etkisini esas al.','Hangisi önce sunulmalı?',('İlaç doz uygulamasında yetkisiz kayıt değişikliği mümkün','Hasta güvenliği ve veri bütünlüğü üzerinde doğrudan önemli etki vardır.'),('Eğitim portalında iki kullanım kılavuzu eski tarihli','Belge güncelliği sorunu verilen koşullarda daha düşük etkilidir.'),('İç toplantı takviminde üç davet onaysız değişmiş','Etkisi klinik karar bütünlüğüyle aynı düzeyde değildir.'),('Yazıcı listesindeki bir cihazın seri numarası eksik','Envanter hatası önemlidir ancak mevcut olayda daha düşük önceliklidir.'),'Önemlilik belge sayısı veya bulgu adedi değildir. Az sayıda kayıt bile hasta güvenliğini etkiliyorsa ciddi olabilir.','Teknik açığı hangi iş sonucuna yol açabileceğiyle anlat; gerçekleşmiş zarar varmış gibi yazma.')
fill(1,'Bulgu ölçütü','Hastanenin onaylı kuralı: ayrılan çalışanların erişimi en geç aynı gün kapatılır. Gözlenen kayıt: ayrılıştan iki gün sonra aktif hesap. Bulgu yazarken onaylı kuralı ayrı başlıkta veriyorsun.','Onaylı kural bulgunun hangi öğesidir?',['ölçüt','kriter'],'Ölçüt, olması gereken durumu tanımlar. Gözlenen durum farklıdır; kök neden ise bu farkın neden oluştuğunu açıklamak için ayrıca araştırılır.','Kuralı ve gözlemi birbirine karıştırmazsan yönetim tartışması somut bir fark üzerinden yürür.')
decision(1,'scenario','Kapsam kısıtı','Pera Ticarette ödeme logları iki kez reddedildi. Yönetim yalnız ekran görüntüsü veriyor. Bu görüntüler dönemin tamamını kapsamıyor. Rapor teslimi yarın.','En uygun yaklaşım hangisi?',('Alternatif kanıtı değerlendirip kalan kısıtı eskale etmek','Önce mümkün güvenceyi araştırır, çözülemeyen sınırlamayı görünür kılar.'),('Ekran görüntülerini tüm dönem için yeterli saymak','Sınırlı görüntüler tüm dönem hakkında kanıt sağlamaz.'),('Raporu olumlu yazıp log talebini sonraya bırakmak','Önemli kanıt eksikliğini sonuca yansıtmadan gizler.'),('Hiçbir sonuç vermeden tüm denetimi sessizce durdurmak','Kısıtın etkisini yetkili tarafa açıklamak ve seçenekleri değerlendirmek gerekir.'),'Kanıt erişiminin engellenmesi sonuç kapsamını etkiler. Alternatif prosedürler yeterli olmazsa bu kısıt rapor ve uygun eskalasyon kanalında açıkça ele alınır.','Taleplerin tarihini, verilen kanıtı ve hangi sonucun desteklenemediğini belgeleyerek yöneticine git.')
decision(1,'choice','Uzman kullanımı','Pera Ticaretin ödeme algoritmasını teknik uzman inceleyecek. Uzman yönetime bağlı çalışıyor ve daha önce algoritmayı geliştirmiş.','Uzmanın sonucuna dayanırken önce neyi değerlendirirsin?',('Yetkinliğini, tarafsızlığını ve inceleme kapsamını','Uzman kullanımı için güvenilirlik ve amaca uygunluk birlikte değerlendirilir.'),('Raporun uzunluğunu ve kullanılan teknik terimleri','Sunum yoğunluğu teknik yeterlilik veya tarafsızlığı kanıtlamaz.'),('Yönetimin uzmandan memnuniyetini ve ücretini','Memnuniyet ve ücret bağımsız güvence ölçütü değildir.'),('Sonucu aynen aktarıp sorumluluğu uzmana bırakmayı','Denetçinin kendi sonucu için sorumluluğu devam eder.'),'Uzmanın bilgisi değerlidir; ancak kendi geliştirdiği sistemi incelemesi tarafsızlık tehdidi yaratır. Kapsam ve çalışma kalitesi de denetim amacına uygun olmalıdır.','Uzman çalışmasına güvenme gerekçeni belgeleyip gerekiyorsa bağımsız doğrulama iste.')
order(1,'Bulgu kapanışı','Pera Ticaret yetki sorununu çözdüğünü söylüyor. Kanıt henüz incelenmedi. Kontrol günlük çalışıyor ve bir haftalık yeni kayıt mevcut.',['Aksiyonun kontrol zayıflığını nasıl giderdiğini incele','Güncel kayıtlarda yeni kontrolün çalışmasını test et','Kalan riski ve test sonucunu değerlendir','Kanıt yeterliyse bulguyu gerekçeyle kapat'],'Aksiyon tamamlandı beyanı kapanış değildir. Önce çözümün tasarımını, ardından gerçek işletimini doğrula; kapanışı bu değerlendirme destekler.','Ticket durumunu değil, riski azaltan kontrolün çalıştığını doğrula.')
decision(1,'drag_select','Kalite incelemesi','Selin (Denetim Yöneticin) dört rapor notundan birini geri gönderiyor. Notlarda kanıt ve sonuç arasında uyum arıyor.','Hangisi yeniden yazılmalı?',('Üç örnekte onay yok; tüm departman sürekli usulsüz çalışıyor','Üç örnek tüm departmanın sürekli davranışını ve niyetini kanıtlamaz.'),('Üç örnekte onay yok; kontrol istisnaları gözlendi','Sonuç gözlenen örneklerle sınırlıdır.'),('Liste tamlığı doğrulanamadı; güvence kapsamı sınırlı','Kanıt kısıtını açıkça belirtir.'),('Yeniden test uygun; incelenen dönem için bulgu kapandı','Kapanışı dönem ve yeniden testle sınırlar.'),'Kalite incelemesi, raporun kanıtın taşıyamayacağı iddialar kurmasını önler. Özellikle genelleme, niyet ve kesin nedensellik ifadeleri daha güçlü dayanak ister.','Kullandığın her önemli sıfat için “hangi kanıt bunu destekliyor?” diye sor.')
decision(1,'scenario','Yönetimle iletişim','Domain 1 kapanışı. Zeynep (Finans Müdürü), kanıtlanan onay sorununu kabul ediyor ama aksiyon sahibini belirlemek istemiyor: “Ekip çözer.”','Toplantıyı en uygun nasıl kapatırsın?',('Yetkili aksiyon sahibi ve tarihi netleştirip kaydetmek','Takip edilebilir aksiyonun sorumluluğu ve süresi açık olmalıdır.'),('Ekip ifadesini yeterli bulup bulguyu kapatmak','Sorumluluğun belirsiz kalması izlemeyi ve kapanışı zayıflatır.'),('Kontrolün sahibi olarak kendi adını yazmak','Denetçi yönetimin kontrol sahipliğini üstlenmemelidir.'),('Tarihi tek taraflı belirleyip yönetim görüşünü çıkarmak','Uygulanabilir aksiyon ve yönetim yanıtı için görüşme gerekir.'),'Denetçi sorunu ve takibi netleştirir; kontrolü işletme sorumluluğu yönetimdedir. Yönetimin yanıtı anlaşmazlık varsa onunla birlikte doğru biçimde kaydedilir.','Kapanış toplantısından “kim, neyi, ne zamana kadar yapacak ve nasıl doğrulanacak?” bilgisiyle çık.')
# DOMAIN 2 — Move from control testing to business accountability.
decision(2,'choice','Stratejik uyum','Lale Teknolojinin yönetim kurulu müşteri kaybını azaltmak istiyor. IT bütçesinin çoğu, müşterinin sorununa dokunmayan bir altyapı yenilemesine gidiyor. Ece (CFO), “Teknik ekip en yeni ürünü seçti” diyor.','Denetçinin önce araması gereken kanıt nedir?',('Yatırımın iş hedefi ve beklenen faydayla bağlantısı','Teknik yatırımın gerekçesi iş değerine dayanmalıdır.'),('Ürünün piyasa sıralaması ve satıcının ödülleri','Ürünün itibarı işletmenin önceliğiyle uyumu kanıtlamaz.'),('Sunucu markaları ve kabin yerleşiminin ayrıntıları','Teknik ayrıntılar yatırımın stratejik gerekçesinden sonra gelir.'),('Geçen yılın bütçesinin aynı oranda artırılması','Bütçe sürekliliği iş ihtiyacının devam ettiğini göstermez.'),'IT stratejisi işletmenin hedeflerini desteklemelidir. Önce hedef, yatırım ve ölçülebilir fayda arasındaki bağı değerlendir; teknoloji tercihini bu bağlamda incele.','“Yeni ürün ne yapıyor?” kadar “hangi iş sonucunu değiştirecek?” sorusunu sor.')
multi(2,'Yönetişim ve yönetim','Lale Teknolojide görevler karışmış. Yönetim kurulu günlük yama takvimini onaylıyor; IT ekibi ise kurumun kabul edeceği kayıp sınırını tek başına belirliyor.','Yönetişim düzeyinde kalması gereken iki karar hangisi?',[('İş hedefleriyle uyumlu IT yönünü belirlemek','Kurumun yönünü belirleme yönetişim sorumluluğudur.'),('Kurumun risk iştahını değerlendirip sınırları onaylamak','Kabul edilecek riskin çerçevesi uygun üst düzeyde belirlenir.'),('Haftalık yama kurulum sırasını işletmek','Günlük uygulama ve işletim yönetim faaliyetidir.'),('Servis masasındaki ticketları personellere dağıtmak','Operasyonel görev dağıtımı yönetişim kararı değildir.')],'Yönetişim ihtiyaçları değerlendirir, yön verir ve sonuçları izler. Yönetim, bu yön doğrultusunda planlar ve işleri yürütür. İki düzey birbirine bilgi vermeli, birbirinin günlük görevini üstlenmemelidir.','Kurulun gündemini iş değeri ve riskle; IT yönetiminin gündemini uygulama ve hizmetle ilişkilendir.')
order(2,'Politika uygulaması','Kent Belediyesi taşınabilir cihaz politikasını yeniliyor. Riskler belirlenmiş; taslak hazır. Henüz onay veya çalışan bildirimi yapılmadı.',['Taslağı yetkili yönetimin onayına sun','Onaylı kuralı ilgili çalışanlara duyur','Uygulama sorumlularına prosedür ve eğitim ver','Uygulama sonuçlarını ve istisnaları izle'],'Bir taslak uygulama yetkisi sağlamaz. Onaylanan kuralın duyurulması ve nasıl uygulanacağının açıklanması gerekir; ardından gerçek uygulama izlenir.','İmzalı PDF bulmakla yetinme; çalışanların ne yapacağını bildiğini ve kuralın işletildiğini kontrol et.')
decision(2,'drag_select','Yönetişim riski','Belediyenin dijital hizmet programında dört açık var. Sonuçlara yönelik hesap verebilirliği en çok zayıflatanı seç.','Önce hangisini gündeme taşırsın?',('Kritik hizmetin risk sahibi ve karar yetkisi belirsiz','Risk kararı ve aksiyonu için hesap verebilir kişi bulunmuyor.'),('Toplantı şablonunda bir eski kurum logosu bulunuyor','Görsel güncellik karar sorumluluğunu belirlemez.'),('Teknik ekip aylık raporu bir gün geç gönderiyor','Gecikme izlenmelidir; sorumluluk yokluğu daha yapısal sorundur.'),('Komite toplantısında sunum süresi kısa tutuluyor','Süre tek başına yönetişim etkinliğini belirlemez.'),'Yönetişimde asıl açık, risk ve karar için hesap verebilirliğin olmamasıdır. Rapor biçimi ve toplantı düzeni bunun yerini tutmaz.','Risk kaydına karar yetkisi olan bir iş sahibi bağlanmasını iste.')
fill(2,'Risk sahipliği','Belediyenin vatandaş portalında veri sızıntısı riski var. IT ekipleri kontrolü işletiyor; hizmetin iş sonuçları ve kalan risk kararı ise yetkili hizmet yöneticisine ait.','Bu yönetici risk kaydında hangi rolü üstlenir?',['risk sahibi','riskin sahibi'],'Risk sahibi riskin iş etkisini değerlendirir ve yetkisi içindeki risk kararından sorumludur. Kontrolü işleten kişiyle aynı olmak zorunda değildir.','Kayıtta kontrol sahibi, aksiyon sahibi ve risk sahibini ayrı ve anlaşılır göster.')
decision(2,'scenario','Risk kabulü','Ece (CFO), belediye portalındaki açığı “bütçe yok” diyerek bir yıl ertelemek istiyor. Risk iştahı bu düzeyde veri kaybına izin vermiyor.','En uygun denetim yaklaşımı nedir?',('Yetki ve iştah sınırını doğrulayıp kararı eskale etmek','Yetkisiz veya iştah dışı kabul uygun karar merciine taşınmalıdır.'),('CFO imzası varsa riski otomatik kapatmak','Bir imza yetki sınırını ve kabul edilebilirliği tek başına sağlamaz.'),('Açığı bizzat kapatıp risk sahibinin rolünü üstlenmek','Denetçi operasyonel kontrol sorumluluğunu almamalıdır.'),('Bütçe sorunu olduğu için risk kaydını kaldırmak','Maliyet gerekçesi riskin varlığını ortadan kaldırmaz.'),'Risk kabulü bilinçli, yetkili ve sınırları belli bir karardır. Kabul edilen risk de izlenir. İştah dışındaki karar, uygun yönetim düzeyine taşınmalıdır.','Kalan risk, karar sahibi, süre ve izleme koşullarını görünür tut.')
decision(2,'choice','Kurumsal mimari','Ufuk Sağlıkta aynı hasta için dört sistem farklı kimlik numaraları tutuyor. Yeni uygulama projesi beşinci bağımsız listeyi kuracak.','Mimari incelemede en uygun odak hangisi?',('Ortak veri ve entegrasyon gereksinimlerinin uyumu','Yeni çözümün kurumsal veri ve iş akışlarıyla uyumunu değerlendirir.'),('Yeni uygulamanın ekranlarının mevcutlara benzemesi','Görsel benzerlik veri tutarlılığı sağlamaz.'),('Her sistem için ayrı raporlama ekibi kurulması','Ek ekipler temel veri ve entegrasyon sorununu çözmez.'),('En hızlı teslim eden satıcının doğrudan seçilmesi','Hız, mimari uyumu ve veri bütünlüğünü garanti etmez.'),'Kurumsal mimari, uygulama seçimini veri, süreç ve teknoloji bağımlılıklarıyla birlikte ele alır. Yeni bir ada yaratmak veri tutarsızlığını büyütebilir.','Sadece proje teslimini değil, çözümün kurumun bütünüyle nasıl çalışacağını sorgula.')
order(2,'Risk yönetimi','Ufuk Sağlığın uzaktan muayene hizmeti için ilk risk değerlendirmesi yapılacak. Kapsam belirlendi; varlık envanteri henüz yok.',['Hizmeti destekleyen varlıkları ve sahiplerini belirle','Tehditleri ve ilgili kontrol açıklarını incele','Olasılık ve iş etkisini birlikte değerlendir','Uygun risk yanıtını yetkili sahiplerle kararlaştır'],'Risk değerlendirmesi varlığı ve iş bağlamını bilerek başlar. Yanıt seçimi ise olasılık, etki ve mevcut kontroller anlaşıldıktan sonra yapılır.','Önce araç satın alıp sonra gerekçe arama; hangi riske cevap verdiğini baştan tanımla.')
decision(2,'drag_select','Tedarikçi yönetişimi','Hastanenin dış hizmet sözleşmelerini inceliyorsun. En büyük hesap verebilirlik boşluğunu seç.','Hangi sözleşme önce incelenmeli?',('Hasta verisi hizmetinde kurum ve satıcı sorumlulukları belirsiz','Hassas ve kritik hizmette kontrol sahipliği belirsiz kalır.'),('Yemekhane yazılımında yenileme tarihi yaklaşıyor','Verilen bilgi sorumluluk açığını göstermiyor.'),('Eğitim hizmetinde aylık toplantı tutanağı geç geldi','Tek bir gecikme daha dar bir süreç sorunudur.'),('Ziyaretçi uygulamasında iletişim kişisi güncellendi','Sorumlu kişinin güncellenmesi tek başına olumsuz bulgu değildir.'),'Dış kaynak kullanımı kurumun gözetim sorumluluğunu bitirmez. Özellikle veri, kesinti ve olay yönetiminde kimin ne yapacağı sözleşmede ve uygulamada belirli olmalıdır.','Satıcının sorumlulukları kadar kurumun yapması gerekenleri de kontrol et.')
decision(2,'scenario','Üçüncü taraf güvence','Bulut sağlayıcısı bir güvence raporu gönderdi. Rapor dönemi altı ay önce bitiyor, hasta verisi hizmeti kapsam dışı; kurumun uygulaması gereken kontroller ek bölümde.','En uygun karar nedir?',('Kapsam boşluğunu ve kurum kontrollerini ayrıca değerlendirmek','Rapora güvenmek için dönem, hizmet kapsamı ve kurum yükümlülükleri uyumlu olmalıdır.'),('Sağlayıcı tanınmış olduğu için raporu yeterli saymak','İtibar kapsam dışındaki hizmete güvence sağlamaz.'),('Ek bölümdeki kontrolleri yalnız satıcıya havale etmek','Kurumun uygulaması gereken kontroller kurumda doğrulanmalıdır.'),('Rapor bulunduğu için tüm satıcı testlerini kaldırmak','Raporun gerçek kapsamı görülmeden testlerden vazgeçilemez.'),'Bir raporun varlığı tüm hizmetleri kapsadığı anlamına gelmez. Dönem aralığı, hariç tutulan hizmetler ve kullanıcı kurum kontrolleri ayrı değerlendirilir.','Güvenceyi rapor başlığından değil, kendi hizmetinle eşleştirdiğin kapsamdan çıkar.')
decision(2,'choice','Performans ölçümü','Duru E-ticarette IT raporu yalnız kapatılan ticket sayısını gösteriyor. Ekip sayıyı artırmak için aynı sorunu küçük ticketlara ayırıyor. Müşteri bekleme süresi uzamış.','Hangi ölçüm daha anlamlı bir tamamlayıcı olur?',('İş etkisiyle birlikte çözüm süresi ve tekrar oranı','Hizmet sonucunu ve kalitesini sayıyla birlikte görünür kılar.'),('Ticketların toplam karakter ve ek dosya sayısı','Belge hacmi hizmetin iş sonucunu ölçmez.'),('IT çalışanlarının gönderdiği e-posta sayısı','Faaliyet miktarı çözüm kalitesine eşit değildir.'),('Kapatılan ticket sayısını tek başına daha sık ölçmek','Aynı yanlış teşviki sık ölçmek sorunu çözmez.'),'Bir gösterge davranışı etkiler. Yalnız hacim ölçmek verim izlenimi yaratabilir; kalite, süre ve iş etkisiyle birlikte okumak gerekir.','Göstergeyi iyileştiren davranışın hizmeti de iyileştirip iyileştirmediğini sorgula.')
multi(2,'Veri yönetişimi','Duru E-ticarette müşteri verisinin sahibi ve saklama kararı belirsiz. Kurum iki işlevi eşleştirmek istiyor.','Doğru olan iki rol–sorumluluk çiftini seç.',[('İş veri sahibi → verinin iş amacı ve sınıflandırma kararı','İş bağlamını ve kullanım ihtiyacını veri sahibi belirler.'),('Teknik veri sorumlusu → onaylı saklama ve erişim kurallarını işletme','Teknik uygulama onaylı kurallara göre yürütülür.'),('Denetçi → tüm müşterilerin saklama süresini tek başına belirleme','Denetim kontrolü değerlendirir; iş ve hukuk kararının sahibi olmaz.'),('Satıcı satış ekibi → kurumun veri sınıfını tek başına değiştirme','Satıcı kurumun veri sahipliğini devralmaz.')],'Sahiplik, veriyle ilgili iş kararlarını kimin verdiğini netleştirir. Teknik sorumlu bu kararları uygular; denetçi ise karar ve uygulamanın uygunluğunu inceler.','Veri için “herkes sorumlu” ifadesi yerine karar ve uygulama sahiplerini isimlendirilmiş rollerle göster.')
order(2,'Tedarikçi seçimi','Duru E-ticaret yeni çağrı merkezi hizmeti alacak. Sözleşme henüz imzalanmadı. Dört hazırlık işi sırasını bekliyor.',['İş gereksinimlerini ve veri risklerini tanımla','Adayların yeterliliğini ve kontrollerini değerlendir','Sorumluluk, hizmet düzeyi ve çıkış şartlarını kararlaştır','Yetkili onayla sözleşmeyi imzala'],'İhtiyacı ve riski bilmeden teklifleri karşılaştırmak fiyatı tek ölçüt haline getirir. Kritik yükümlülükler imzadan önce kararlaştırılmalıdır.','Sözleşme incelemesine çıkış, veri iadesi ve kontrol doğrulama hakkını dahil et.')
decision(2,'drag_select','Görevler ayrılığı','Lale Teknolojide ekip küçülmüş. Dört görev birleşiminden hangisi üzerinde telafi kontrolü önceliklidir?','En önemli çatışmayı seç.',('Aynı kişi satıcıyı açıyor ve satıcı ödemesini onaylıyor','Kayıt oluşturma ve ödeme yetkisi birleşince uygunsuz işlem gizlenebilir.'),('Aynı kişi raporu hazırlıyor ve toplantıda sunuyor','Bu işler tek başına işlem oluşturma–onay çatışması değildir.'),('Aynı kişi eğitim takvimini yazıyor ve salon ayırıyor','Verilen işlerde önemli mali işlem yetkisi çakışması yoktur.'),('Aynı kişi envanteri okuyor ve eksik cihazı bildiriyor','Okuma ve bildirim yetkileri işlem onayıyla aynı değildir.'),'Görevler ayrılığı, bir kişinin uygunsuz işlemi başlatıp onaylayarak gizleme imkanını azaltır. Küçük ekiplerde bağımsız ve kanıtlanabilir inceleme gibi telafi kontrolleri gerekebilir.','İdeal organizasyonu istemekle yetinme; işleyen bağımsız incelemenin kapsamını ve sıklığını test et.')
fill(2,'Kalan risk','Lale Teknoloji güçlü erişim kontrolleri kurdu. Yine de ayrıcalıklı hesabın kötüye kullanılma olasılığı tamamen sıfır olmadı.','Kontrollerden sonra devam eden riskin adı nedir?',['kalan risk','artık risk','residual risk'],'Kontroller olasılığı veya etkiyi düşürebilir; genellikle riski tamamen yok etmez. Karar, bu kalan riskin iştah ve yetki sınırlarına uygun olup olmadığıyla ilgilidir.','Kontrol kuruldu diye risk kaydını silme; kalan düzeyi ve izleme koşulunu güncelle.')
decision(2,'scenario','Bulutta sorumluluk','Küresel lojistik şirketi Kuzey Rota buluta geçti. Arda (Bulut Yöneticisi), “Sunucuyu onlar yönetiyor, bütün güvenlik de onların işi” diyor. Kurumun hesap ve veri ayarları hâlâ kendi elinde.','En uygun yanıt hangisi?',('Hizmet modeline göre ortak sorumlulukları doğrulamak','Sağlayıcı ve kurum yükümlülükleri model ve sözleşmeye göre farklılaşır.'),('Bulut olduğu için tüm kontrolleri sağlayıcıya bırakmak','Kurumun kimlik, veri ve yapılandırma sorumluluğunu görmezden gelir.'),('Bütün fiziksel kontrolleri kurum personeline aktarmak','Fiziksel altyapı sorumluluğu hizmet modelinde sağlayıcıda olabilir.'),('Sadece faturayı inceleyip kontrol kapsamını kapatmak','Fatura hizmet kontrollerinin uygulandığını kanıtlamaz.'),'Bulut sorumluluğu ortadan kaldırmaz, paylaşımını değiştirir. İnceleme, kullanılan modelde kurumun hangi kontrolleri işlettiğini açıkça belirlemelidir.','Sözleşme ve mimari üzerinden sorumluluk matrisi çıkar; sahipsiz kalan kontrolü ara.')
decision(2,'choice','Mahremiyet programı','Kuzey Rota sürücü konumlarını “ileride işe yarar” diye süresiz saklıyor. İş amacı ve saklama gereksinimi belgelenmemiş. Henüz hangi ülkelerin kuralları geçerli olduğu da belirlenmedi.','Önce hangi değerlendirme gerekir?',('İş amacı, gerekli veri ve geçerli yükümlülükler','Toplama ve saklamanın gerekçesini uygun iş ve hukuk bağlamında kurar.'),('Depolama fiyatı ve daha ucuz disk seçimi','Maliyet amaçsız veri toplamayı uygun hale getirmez.'),('Veriyi isteyen yöneticinin kıdemi ve unvanı','Kıdem meşru kullanım ve saklama şartını kanıtlamaz.'),('Verinin tamamını hemen halka açma planı','İnceleme olmadan ifşa veri riskini artırır.'),'Mahremiyet programı verinin neden toplandığını, ne kadar gerekli olduğunu ve hangi şartlarla işlendiğini belirler. Doğrulanmamış hukuk iddiası yerine uygulanabilir yükümlülükler yetkin kişilerle teyit edilir.','“Belki lazım olur” gerekçesini ölçülebilir iş ihtiyacına ve onaylı saklama kararına dönüştür.')
order(2,'Fayda izleme','Kuzey Rotanın optimizasyon projesi bitti. Fayda ölçütü: teslimat gecikmesini azaltmak. Başlangıç verisi mevcut, canlı sistem üç aydır çalışıyor.',['Canlı dönem gecikme verisinin kalitesini doğrula','Sonucu başlangıç değeri ve hedefle karşılaştır','Sapmaların iş ve uygulama nedenlerini incele','Fayda sahibinin düzeltme ve izleme kararını kaydet'],'Fayda izlemesi proje tesliminin ardından iş sonucunu ölçer. Karşılaştırma için güvenilir veri ve ortak tanım gerekir; sapma tek başına yazılım hatası demek değildir.','Teknoloji teslim edildiği için faydanın gerçekleştiğini varsayma.')
decision(2,'drag_select','Olgunluk değerlendirme','Kuzey Rotanın süreçleri yazılı ama çoğu ekip uygulamıyor. Yönetim yüksek olgunluk puanı istiyor.','Hangi kanıt daha güçlüdür?',('Farklı ekiplerde süreç uygulaması ve izleme kayıtları','Sürecin kuruma yayıldığını ve yönetildiğini gösterir.'),('Satın alınmış çerçeve kitabının güncel baskısı','Kitabı edinmek uygulama olgunluğunu kanıtlamaz.'),('Bütün prosedürlerin aynı kapakla tasarlanması','Biçimsel tutarlılık işletim etkinliğine eşit değildir.'),('Yönetici sunumunda büyük bir olgunluk grafiği','Grafiğin dayanağı yoksa bağımsız kanıt değildir.'),'Olgunluk değerlendirmesi yalnız doküman sayısı değildir. Uygulama tutarlılığı, ölçüm ve iyileştirme kanıtı gerektirir.','Puanlama ölçütünü baştan belirle; yönetimin istediği puana göre kanıt seçme.')
decision(2,'scenario','Kurula risk anlatımı','Domain 2 sonu. Kurulun beş dakikası var. Kritik hizmetin risk sahibi hâlâ belirsiz ve bulut sorumlulukları sözleşmeyle uyuşmuyor.','Sunumu nasıl kurarsın?',('İş etkisini, karar ihtiyacını ve sorumluluk açığını anlatmak','Kurulun yön ve hesap verebilirlik kararı vermesine yardımcı olur.'),('Tüm teknik ayarları sırayla okuyup toplantıyı bitirmek','Ayrıntı karar ihtiyacını görünmez kılabilir.'),('Risk kabulünü denetim adına kendin açıklamak','Denetçi yönetimin risk kabul yetkisini üstlenmez.'),('Sözleşme var diye riskleri düşük olarak sunmak','Sözleşmenin varlığı sorumluluk ve uygulama açığını gidermiyor.'),'Üst yönetim sunumu riskin iş anlamını ve hangi karara ihtiyaç duyulduğunu açıklar. Kanıtlı teknik ayrıntılar, bu kararı desteklemek için kullanılır.','Yönetimden somut sahiplik ve düzeltme kararı iste; operasyon talimatını kurul sunumuna doldurma.')
# DOMAIN 3 — Accompany a project without becoming its owner.
decision(3,'choice','İş gerekçesi','Marmara Sigorta hasar uygulamasını yenileyecek. Bora (Proje Sponsoru), “Rakibimiz aldı, biz de almalıyız” diyor. Süreç sorunları ve beklenen fayda henüz tanımlı değil.','İlk hangi eksikliği sorgularsın?',('Ölçülebilir iş ihtiyacı ve yatırım gerekçesini','Proje kararı doğrulanabilir iş ihtiyacı ve fayda üzerine kurulmalıdır.'),('Yeni ürünün arayüz renginin kurumla uyumunu','Görsel uyum projenin neden gerekli olduğunu açıklamaz.'),('Sunumda yeterli sayıda teknik terim olmasını','Teknik dil yatırım değerine kanıt değildir.'),('Rakibin kullandığı lisans paketinin aynısını','Rakibin ihtiyacı kurumun ihtiyacıyla aynı olmayabilir.'),'İş gerekçesi neden yatırım yapıldığını, alternatifleri, maliyeti, riski ve beklenen faydayı görünür kılar. Rekabet gözlemi tek başına gerekçe değildir.','Proje başlamadan başarı ölçütü ve fayda sahibi belirlenirse canlı sonrası değerlendirme mümkün olur.')
multi(3,'Gereksinim kalitesi','Sigortada ödeme üst sınırı ve onay ihtiyacı konuşuldu; gereksinim belgesinde yalnız “güvenli ödeme” yazıyor.','Hangi iki ekleme gereksinimi test edilebilir yapar?',[('Üst sınır aşıldığında ikinci onayın zorunlu olması','Belirli koşul ve beklenen davranış tanımlar.'),('Onaylayan kişinin işlem sahibiyle farklı olması','Görev ayrımının sınanabilir ölçütünü verir.'),('Uygulamanın genel olarak yenilikçi görünmesi','Belirsiz sıfat ölçülebilir kabul ölçütü değildir.'),('Testçinin uygun gördüğü davranışın yeterli sayılması','Önceden tanımlı gereksinimin yerini öznel karar alır.')],'Gereksinim, koşulu ve beklenen davranışı açıkça tanımlar. Böylece test sonucu iş ihtiyacına bağlanır; “güvenli” gibi genel ifadeler farklı kişilerce farklı yorumlanmaz.','İzlenebilirlik tablosunda her kritik gereksinimi bir kabul testiyle eşleştir.')
order(3,'Gereksinim değişikliği','Sigorta projesinde geliştirme sürüyor. Sponsor, ödeme limitinin iki katına çıkarılmasını istedi. Henüz değişiklik onaylanmadı.',['Değişikliğin kapsam, maliyet ve kontrol etkisini değerlendir','Yetkili karar merciinden değişiklik onayı al','Onaylanan gereksinimi ve testleri güncelle','Yeni davranışı uygulayıp güncel testleri çalıştır'],'Yeni talep, risk ve proje etkisi görülmeden uygulanmamalıdır. Onay sonrası gereksinim ve testler birlikte güncellenir; eski testlerin geçmesi yeni limitin güvenliğini göstermez.','Küçük görünen iş değişikliğinin kontrol sınırını değiştirip değiştirmediğini kontrol et.')
decision(3,'drag_select','Uygulama kontrolü','Hasar modülünde dört kontrol öneriliyor. Amacın hatalı girişin işleme girmesini önlemek.','Hangi kontrol bu amaca en doğrudan hizmet eder?',('Ödeme tutarı için iş kuralına uygun aralık doğrulaması','Geçersiz girişin kabulünü işlem başında engeller.'),('Ay sonu tamamlanan ödemelerin arşivlenmesi','Arşivleme giriş doğruluğunu önlemez.'),('Sunucu kapasitesinin haftalık raporlanması','Kapasite izleme veri giriş kuralını uygulamaz.'),('Ödeme ekranının renklerinin standartlaştırılması','Görsel standart işlem doğruluğuna yeterli kontrol değildir.'),'Giriş kontrolü yanlış veriyi işlenmeden yakalar. Kontrolün yeri ve amacı önemlidir; arşiv veya performans önlemi aynı riski karşılamaz.','Kontrol tasarımını “hangi hatayı, hangi aşamada yakalar?” sorusuyla değerlendir.')
fill(3,'Test izlenebilirliği','Hasar ekibi 80 testin geçtiğini söylüyor. Ancak kritik onay gereksiniminin hangi testle doğrulandığı bulunamıyor.','Gereksinimleri testlerle bağlayan tabloya “___ matrisi” denir.',['izlenebilirlik','gereksinim izlenebilirlik','gereksinim izlenebilirliği'],'İzlenebilirlik, test sayısından farklıdır. Hangi iş ihtiyacının hangi test ve sonuçla doğrulandığını gösterir; kapsanmayan kritik gereksinimleri görünür kılar.','Yüksek test sayısı yerine kritik gereksinimlerin kapsamını ve test kanıtını incele.')
decision(3,'scenario','Çevik geliştirme','Ada Yazılım iki haftalık sprintlerle çalışıyor. Elif (Ürün Sahibi), “Çevik projede kontrol belgesi olmaz” diyor. Backlog var; kabul ölçütleri ve güvenlik testleri yok.','En uygun yaklaşım hangisi?',('Kontrol ve kabul kanıtını çevik iş akışında aramak','Kontrol ihtiyacı sürer; kanıtın biçimi backlog ve otomasyon olabilir.'),('Çevik yöntem nedeniyle güvenlik testini kaldırmak','Yöntem değişikliği kontrol gereksinimini ortadan kaldırmaz.'),('Her sprint için zorunlu yüz sayfalık rapor istemek','Kanıtın gereksiz biçimini dayatmak kontrol etkinliğini artırmaz.'),('Ürün sahibinin sözlü kabulünü tüm testlere eşit saymak','Beyan kritik gereksinim testinin kanıtı değildir.'),'Çevik yaklaşım, kısa ve izlenebilir kanıtlarla da kontrol sağlayabilir. Kabul ölçütleri, görev ayrımı ve otomatik test sonuçları yöntemle uyumlu biçimde uygulanır.','Ekibe kullanılan araç içindeki kanıtı sor; kontrol amacından vazgeçmeden belge yükünü orantılı tut.')
decision(3,'choice','Kullanıcı kabul testi','Ada Yazılımda geliştiriciler bütün teknik testleri geçti. Satış ekibi henüz iade sürecini denemedi. Yarın canlıya çıkılacak.','Hangi kanıt eksik?',('İş kullanıcılarının gerçek süreçle kabul testi','Teknik çalışma, iş ihtiyacının karşılandığını tek başına göstermez.'),('Geliştiricilerin aynı birim testini yeniden çalıştırması','Aynı teknik test iş kabul kapsamı yaratmaz.'),('Satıcının ürünün başarılı olduğuna dair sunumu','Satıcı beyanı kurumun iş süreci kabulü değildir.'),('Yeni uygulamanın logosunun onaylanması','Logo onayı işlevsel kabul kanıtı sağlamaz.'),'Kullanıcı kabul testi gerçek iş akışını ve önceden belirlenen kabul ölçütlerini doğrular. Teknik testler önemlidir; iş süreciyle doğrulamanın yerini tutmaz.','İş sahibinin hangi senaryoyu hangi sonuçla kabul ettiğini belgeleyen kanıt iste.')
order(3,'Veri dönüşümü','Ada Yazılımın eski müşteri verisi yeni şemaya taşınacak. Canlı taşıma henüz başlamadı. Eşleme kuralları da taslak.',['Alan eşleme ve dönüşüm kurallarını onaylat','Deneme dönüşümünü kontrollü ortamda çalıştır','Kayıt, tutar ve kritik alanları kaynakla mutabık kıl','Hataları giderip canlı geçiş için kabul al'],'Taşıma teknik bir kopyalama işlemi değildir. Alan anlamları, toplamlar ve kritik değerler doğrulanmalı; kabul bu doğrulamanın ardından verilmelidir.','Kayıt sayısı aynı olsa bile tutar, anahtar ve anlam eşlemesinde hata olabileceğini test et.')
decision(3,'drag_select','Dönüşüm kanıtı','Deneme taşımasında 12.000 kaynak kaydı ve 12.000 hedef kaydı var. Dört kontrol sonucu geldi.','Hangi bulgu canlı geçişi en çok sorgulatır?',('Hedef toplam alacak, kaynak toplamından 800 bin TL farklı','Kayıt sayısı eşit olsa bile önemli mali veri tutarsızdır.'),('Taşıma raporu bir sayfa daha kısa hazırlanmış','Biçim farkı veri doğruluğunu tek başına etkilemez.'),('Test dosyalarının adları yeni standarda çevrilmiş','Ad değişimi içerik hatasını göstermez.'),('Yeni ekran eski ekrandan daha hızlı açılmış','Performans iyileşmesi veri bütünlüğü açığını göstermez.'),'Kayıt sayısı, yalnız bir mutabakat ölçüsüdür. Mali toplamlar ve kritik alan doğruluğu da gerekir. Önemli tutar farkı araştırılıp çözülmeden kabul yeterli değildir.','Sayısal eşitliklerin neyi doğruladığını ayrı yaz; bir ölçümü bütün dönüşüm güvencesi gibi sunma.')
decision(3,'scenario','Geri dönüş planı','Satış uygulamasında testler geçti. Geçiş başarısız olursa eski sisteme dönüş adımları hiç denenmedi. Bora (Sponsor), “Gerekirse düşünürüz” diyor.','En uygun denetim önerin nedir?',('Geri dönüş koşulları ve adımlarını geçiş öncesi doğrulamak','Başarısızlık halinde kontrol edilebilir ve test edilmiş alternatif gerekir.'),('Eski sistemi geçiş başında hemen silmek','Geri dönüş imkanını ortadan kaldırabilir.'),('Testler geçtiği için dönüş ihtiyacını yok saymak','Başarı testleri canlı geçişte arıza olmayacağını garanti etmez.'),('Dönüş sorumluluğunu yalnız çağrı merkezine vermek','Teknik veri ve sistem adımları yetkin sahipler gerektirir.'),'Geri dönüş planı hangi koşulda karar verileceğini, kimin yetkili olduğunu ve verinin nasıl korunacağını belirtir. Denenmemiş bir niyet plan sayılmaz.','Yeni sistemde yapılan işlemlerin eskiye dönüşte nasıl ele alınacağını da sorgula.')
decision(3,'choice','Test türleri','Kent Belediyesinin tahsilat modülü tek başına doğru çalışıyor. Banka arayüzüne bağlandığında çift kayıt oluşuyor.','Bu sorunu en doğrudan hangi test yakalar?',('Entegrasyon testi; tahsilat ve banka akışını birlikte sınar','Sorun bileşenlerin birlikte çalışma sınırında oluşuyor.'),('Birim testi; yalnız tek fonksiyonun kodunu sınar','Tek bileşen testi sistemler arası etkileşimi tam kapsamaz.'),('Görsel test; ekran renklerinin uyumunu sınar','Görünüm çift işlem oluşturma davranışını doğrulamaz.'),('Lisans testi; ürünün kullanım hakkını sınar','Lisans uygunluğu işlem entegrasyonunu test etmez.'),'Birim testleri geçse bile arayüz ve entegrasyon hataları kalabilir. Testin seviyesi, hatanın oluştuğu sistem sınırına uygun seçilmelidir.','Ayrı ayrı başarılı modüllerin birlikte aynı işi doğru yaptığına dair kanıt ara.')
multi(3,'Canlıya çıkış ölçütü','Belediyenin tahsilat geçiş toplantısında dört kayıt inceleniyor. İki kayıt canlıya çıkış güvencesini doğrudan destekliyor.','Bu iki kaydı seç.',[('Kritik testlerin sonucu ve iş sahibinin kabulü','Sistemin kritik iş ihtiyacını karşıladığına dayanak sağlar.'),('Denemesi yapılmış geri dönüş planı ve karar yetkisi','Başarısızlık halinde kontrollü hareket imkanı sağlar.'),('Proje ekibinin kutlama toplantısı daveti','Kutlama hazırlığı sistem hazır olma kanıtı değildir.'),('Geliştiricinin takvimde boş vakti kalmaması','Kaynak baskısı geçiş kontrolü yerine kullanılamaz.')],'Canlıya çıkışta başarı koşulları ve başarısızlık planı birlikte değerlendirilir. Takvim baskısı, kabul kanıtı veya geri dönüş hazırlığının yerini tutmaz.','Denetçi risk ve kanıtı sunar; yetkili yönetim belgeli geçiş kararını verir.')
order(3,'Sürüm yönetimi','Tahsilat düzeltmesi hazır. Değişiklik onayı ve bağımsız test tamamlandı. Şimdi üretime taşınacak paketin izlenebilirliği gerekiyor.',['Onaylı sürüm paketini kimliğiyle sabitle','Paketi yetkili yayın hesabıyla üretime aktar','Üretimdeki sürümün onaylı paketle eşleştiğini doğrula','Yayın ve doğrulama kanıtını değişiklik kaydına bağla'],'Üretime giren kod, test edilen ve onaylanan kodla aynı olmalıdır. Paket kimliği ve yayın kanıtı bu bağı kurar.','“Test edildi” ifadesini sürüm kimliği olmadan kabul etme.')
decision(3,'drag_select','DevOps kontrolü','Ada Yazılımın dört CI/CD hattı var. Amaç bağımsız onayı atlayarak üretime kod taşınmasını önlemek.','Hangi ayar en büyük riski yaratır?',('Geliştirici korumalı dal kuralını tek başına aşabiliyor','Bağımsız onay mekanizması aynı kişi tarafından devre dışı kalabilir.'),('Test sonuçları merkezi depoda saklanıyor','Kanıt saklama tek başına açık değildir.'),('Üretim yayın hesabının yetkisi sınırlanmış','Sınırlı yetki tanımlı amaçla uyumludur.'),('Sürüm paketinin bütünlük özeti kaydediliyor','Paket izlenebilirliğini ve bütünlük doğrulamasını destekler.'),'Otomatik hat, görevler ayrılığını kendiliğinden sağlamaz. Kuralları kimin değiştirebildiği ve korumayı kimin aşabildiği de kontrolün parçasıdır.','Normal akışı test ederken yönetici istisnası ve bypass yetkisini ayrıca incele.')
fill(3,'Geçiş yöntemi','Belediye bir hafta boyunca eski ve yeni tahsilat sistemini birlikte çalıştırıp sonuçlarını karşılaştıracak.','Bu geçiş yaklaşımı nedir?',['paralel','paralel geçiş','paralel çalışma'],'Paralel geçiş, eski ve yeni sistemin birlikte çalışmasıyla sonuçları karşılaştırma imkanı verir. Daha fazla operasyon yükü getirir; çifte işleme riski ayrıca yönetilmelidir.','Yöntemin adını bilmekten öte, karşılaştırma ve işlem sahipliği kontrollerini sorgula.')
decision(3,'scenario','Denetçinin proje rolü','Bora (Sponsor), Kent Belediyesinin geçiş onayına senin imzanı istiyor: “Denetim imzalarsa risk biter.” Sen hazırlık incelemesini yaptın ama proje kararı yetkin yok.','En uygun yanıt hangisi?',('Risk görüşünü sunup kararın yetkili iş sahibinde kalmasını istemek','Güvence rolünü ve yönetimin geçiş sorumluluğunu ayırır.'),('Geçiş kararını denetim adına tek başına onaylamak','Denetçiyi operasyonel kararın sahibi haline getirir.'),('Projedeki bütün risklerin bittiğini yazmak','İnceleme mutlak güvence veya sıfır risk sağlamaz.'),('Risk görüşünü vermeden projeden tamamen çekilmek','Rol sınırını koruyarak değerli güvence sunmak mümkündür.'),'Denetçi proje hazırlığını değerlendirir ve riskleri bildirir. Yetkisiz geçiş onayı vermek, sonradan aynı kararı bağımsız değerlendirmeyi de zorlaştırır.','İnceleme sonucuna kapsamını ve sınırlamalarını ekle; karar sorumluluğunu doğru rolde bırak.')
decision(3,'choice','Uygulama sonrası inceleme','Marmara Sigorta sistemi üç aydır canlıda. Zamanında teslim edildi; fakat hasar işlem süresi hedeflenen 2 günden 5 güne çıkmış.','En uygun inceleme odağı nedir?',('Gerçek fayda, süreç etkisi ve kontrol sonuçları','Canlı sonrası inceleme teslimi değil iş sonucunu da değerlendirir.'),('Proje takvimini tekrar okuyup başarı ilan etmek','Zamanında teslim beklenen faydanın gerçekleştiğini kanıtlamaz.'),('Yalnız yeni uygulamanın lisans sayısını saymak','Lisans sayısı hasar sürecinin etkisini açıklamaz.'),('Gecikmeyi kanıtsız biçimde tek geliştiriciye bağlamak','Nedensellik süreç ve kullanım kanıtıyla araştırılmalıdır.'),'Uygulama sonrası inceleme iş gerekçesindeki faydayı, maliyeti ve kontrol etkinliğini gerçek sonuçlarla karşılaştırır. Olumsuz sonuç için kök neden kanıta dayanmalıdır.','İlk iş gerekçesini canlı veriye bağla; kullanıcı eğitimi ve süreç değişikliğini de incele.')
order(3,'İzlenebilir hata düzeltme','Sigortada iş kullanıcıları yanlış ücret hesaplandığını bildirdi. Hata henüz doğrulanmadı; doğrudan üretim düzeltmesi öneriliyor.',['Hatayı kontrollü ortamda yeniden üret','Kök neden ve etkilenen kayıt kapsamını belirle','Düzeltmeyi test edip yetkili değişiklik onayı al','Kontrollü yayın sonrası sonuçları doğrula'],'Önce hata ve kapsam doğrulanır. Düzeltmenin mevcut sorunu giderirken başka süreçleri bozmadığı test edilir; yayın sonucu da kontrol edilir.','Acil baskıda bile kanıtlı teşhis ve kontrollü değişiklik zincirini koru.')
decision(3,'drag_select','Proje risk önceliği','Sigorta projesinin kapanışında dört açık var. Müşteri ödemelerini doğru işletmek öncelik.','Hangisi önce ele alınmalı?',('Ücret hesaplama farkı sürüyor, etkilenen kayıt kapsamı bilinmiyor','Devam eden mali hata ve bilinmeyen kapsam önemli iş riski yaratır.'),('Eğitim sunumunun kapak tarihi eski kalmış','Sunum biçimi mevcut mali hata kadar doğrudan etki yaratmaz.'),('Arşiv klasörünün adı yeni standarda uymuyor','Adlandırma sorunu hesaplama riskini açıklamaz.'),('Kapanış toplantısı bir gün ertelenmiş','Takvim kayması tek başına kritik kontrol arızası değildir.'),'Proje kapanışı iş riskini yok etmez. Devam eden hesaplama hatası için kapsam, düzeltme ve geçici kontrol belirlenmelidir.','İdari teslim işlerini tamamlamak, açık iş hatasını kapatmak anlamına gelmesin.')
decision(3,'scenario','Proje sonucu iletişimi','Domain 3 kapanışı. Bora (Sponsor), “Gecikmeyi yazmayın; projenin imajı bozulur” diyor. Veriler doğrulandı ama teknik kök neden henüz net değil.','Raporda en uygun yaklaşım nedir?',('Doğrulanan etkiyi ve kök neden belirsizliğini birlikte yazmak','Hem kanıtlı sonucu hem kanıtın sınırını doğru sunar.'),('İmajı korumak için doğrulanmış gecikmeyi çıkarmak','Önemli olgunun gizlenmesi bağımsız raporlamayı bozar.'),('Kanıt olmadan tedarikçiyi kesin sorumlu ilan etmek','Olumsuz sonuç tek başına teknik nedensellik değildir.'),('Neden bilinmiyor diye iş etkisini önemsiz saymak','İş etkisi neden araştırması tamamlanmadan da önemli olabilir.'),'Dürüst raporlama hem gerçek etkiyi gösterir hem bilmediğini belirtir. Yönetim görüşü kaydedilebilir; ancak kanıtlı bulgu baskıyla çıkarılmaz.','“Ne oldu?” ile “neden oldu?” sorularını ayrı cevapla; belirsizliği saklamak yerine araştırma aksiyonu tanımla.')
# DOMAIN 4 — Service operations and a recovery exercise.
decision(4,'choice','Varlık envanteri','Aras Veri Merkezinde bakım sözleşmesi biten bir sunucu bulundu. Canlı müşteri hizmetine bağlı mı bilinmiyor. Cem (Operasyon Müdürü) cihazı hemen kapatmak istiyor.','İlk neyi doğrularsın?',('Cihazın sahibi, iş hizmeti ve teknik bağımlılıkları','Etki ve uygun aksiyon için varlığın kullanım bağlamı bilinmelidir.'),('Cihazın rengini ve raf etiketinin tasarımını','Görsel bilgi hizmet etkisini açıklamaz.'),('Eski satın alma fiyatını tek karar ölçütü yapmak','Satın alma fiyatı bugünkü kritikliği göstermez.'),('Sahibi bilinmediği için cihazı doğrudan hurdaya ayırmak','Bilinmeyen bağımlılığı kesmek hizmet kaybına yol açabilir.'),'Envanter bir seri numarası listesi değildir. Sahiplik, kullanım ve bağımlılık bilgisi bakım, değişiklik ve süreklilik kararlarını destekler.','Sahipsiz kaydı önce iş bağlamına bağla; belirsizliği operasyonel risk olarak görünür tut.')
multi(4,'Toplu işlem kontrolü','Duru E-ticaret gece sipariş aktarımı yapıyor. Kaynakta 3.000 işlem var; hedefte 2.980. Hata kuyruğunda 20 kayıt bekliyor.','Hangi iki kontrol uygun?',[('Kaynak, hedef ve hata kayıtlarını toplamla mutabık kılmak','Tüm kayıtların hangi durumda olduğunu izler.'),('Hata kayıtlarına sahip ve yeniden işleme takibi atamak','Eksiklerin çözülmesini ve kaybolmamasını sağlar.'),('Hedefteki 2.980 kaydı tüm aktarım başarılı saymak','20 istisna tamamlanmadan bütün aktarım başarıyla sonuçlanmış değildir.'),('İşlemi takip etmeksizin tekrar çalıştırıp çoğaltmak','Kontrolsüz tekrar çift kayıt yaratabilir.')],'Aktarım kontrolü yalnız başarılı kayıtları saymaz; hataları da izler. Yeniden işleme çift kayda yol açmayacak şekilde tasarlanmalıdır.','3.000 = 2.980 + 20 eşitliği tamlığı açıklar; 20 kaydın iş sonucu hâlâ ayrıca çözülmelidir.')
order(4,'Olay yönetimi','Ödeme API’si durmuş. İnsan güvenliği etkisi yok; ekip kesintiyi doğruladı. Kurumun onaylı olay akışı bu dört adımı gerektiriyor.',['Olayı kaydet ve iş etkisine göre önceliklendir','Yetkili müdahale ekibini devreye al','Onaylı çözümle hizmeti geri getir','Sonucu doğrula ve kullanıcı iletişimini tamamla'],'Olay yönetiminin önceliği hizmeti kontrollü biçimde geri getirmektir. Kalıcı kök neden incelemesi gerekirse problem yönetimine taşınır.','Hizmet döndü diye olay kaydını kanıtsız kapatma; iş sahibinin hizmet doğrulamasını al.')
decision(4,'drag_select','Problem yönetimi','Kesinti sonrasında üç olay kapanmış. Dördüncü kayıt aynı hatayla bu ay beşinci kez oluşmuş.','Problem incelemesine hangi kayıt öncelikli? ',('Aynı veritabanı kilidi beş kez hizmet kesmiş','Tekrarlama altta yatan çözülmemiş neden göstergesidir.'),('Tek seferlik kullanıcı parolası unutulmuş','Verilen koşul tekrarlayan sistem nedeni göstermiyor.'),('Planlı bakım bildirimi zamanında gönderilmiş','Bu kayıt bir arıza göstergesi değildir.'),('Yeni çalışan için cihaz talebi açılmış','Hizmet talebi tekrarlayan arızayla aynı değildir.'),'Olay çözümü hizmeti döndürür; problem yönetimi tekrarlamanın nedenini ve kalıcı önlemi araştırır. İki süreç bağlantılı ama farklı amaçlıdır.','Tekrarlanan ticketların ortak nedenini analiz et; sadece kapanma hızını ölçme.')
fill(4,'RPO hesaplama','Aras Veri Merkezi tatbikatında işin kabul ettiği veri kaybı 15 dakika. Kesinti 10.00, kullanılabilir son veri 09.35. Gerçek veri kaybı penceresi hedefi aşmış.','Kabul edilebilir veri kaybı hedefinin kısaltması nedir?',['RPO'],'RPO kabul edilebilir veri kaybı zamanını ifade eder. Bu vakada 25 dakikalık kayıp penceresi 15 dakikalık hedefi aşar. RTO ise hizmetin geri dönüş süresiyle ilgilidir.','Hedef ile ölçülen sonucu ayrı sütunlara yaz; iki zaman kavramını karıştırma.')
decision(4,'scenario','Yama yönetimi','Aras Veri Merkezinde internete açık sunucuda önemli açık var. Yama uygulamanın çalışmasını etkileyebilir. Cem (Operasyon Müdürü), “Her yamayı altı ay bekletiyoruz” diyor.','En uygun yaklaşım hangisi?',('Riske göre test, geçici önlem ve yayın planı belirlemek','Maruziyet ve uyumluluk riski birlikte değerlendirilir.'),('Önem derecesine bakmadan altı ay ertelemek','Sabit bekleme yüksek riskli maruziyeti sürdürür.'),('Test olmadan bütün sunuculara aynı anda kurmak','İş sürekliliği ve uyumluluk riski kontrolsüz büyüyebilir.'),('Açık bilgisini kayıt dışı bırakıp ticketı kapatmak','Risk izlenebilirliğini kaybettirir; çözüm sağlamaz.'),'Yama yönetimi hem güvenlik açığını hem hizmet etkisini dikkate alır. Test, kademeli yayın ve uygulanamayan sürede risk azaltımı uygun koşullarla belirlenir.','Takvim kuralını riskin yerine koyma; istisna sahibini, süresini ve geçici kontrolünü kaydet.')
decision(4,'choice','Kapasite yönetimi','Duru E-ticarette CPU ortalaması düşük. Kampanya günleri ödeme yanıtları zaman aşımına uğruyor; veritabanı bağlantıları sınırına geliyor.','Hangi değerlendirme daha uygun?',('Yoğun saatlerde uçtan uca hizmet kapasitesini incelemek','Ortalama CPU tek darboğazı veya yoğun zaman etkisini açıklamaz.'),('CPU ortalaması düşük olduğu için kapasiteyi yeterli saymak','Ortalama, işin en kritik yoğun dönemini gizleyebilir.'),('Yalnız ofis internet hızını iki katına çıkarmak','Kanıtlanan darboğazı hedeflemiyor.'),('Kampanya ticketlarını kapanan işler listesine aktarmak','İdari işlem gerçek kapasite sorununu gidermez.'),'Kapasite yönetimi bileşenleri ve iş talebini birlikte değerlendirir. Yoğun saat, gecikme, kuyruk ve bağlantı sınırları ortalama kaynak kullanımından farklı bilgi sağlar.','Müşterinin tamamlayabildiği işlem sayısını teknik ölçümlerle birlikte oku.')
order(4,'İş etki analizi','Ufuk Sağlık süreklilik planını yeniliyor. Önce iş süreçlerinin tolere edebileceği kesintiyi belirlemek gerekiyor; teknik çözüm seçilmedi.',['Kritik klinik süreçleri iş sahipleriyle belirle','Kesinti süresine göre hasta ve operasyon etkisini değerlendir','Gerekli kurtarma hedeflerini ve bağımlılıkları onaylat','Hedeflere uygun kurtarma seçeneklerini değerlendir'],'İş etki analizi teknik seçenekten önce ihtiyacı belirler. Bütçe ve çözüm kararı işin onayladığı süre ve bağımlılıklara dayanmalıdır.','Hazır satın alınmış kurtarma hizmetinin süresini doğrudan iş hedefi diye yazma.')
decision(4,'drag_select','Süreklilik bağımlılığı','Hastanenin klinik uygulaması yedek merkezde açılıyor. Kullanıcılar giriş yapamıyor. Dört bağımlılıktan biri yedek planda yok.','Hangi eksik bu belirtiyle en doğrudan ilgili?',('Kimlik doğrulama hizmeti yedek merkezde çalışmıyor','Uygulama açık olsa bile kullanıcı girişi sağlanamaz.'),('Eğitim portalının görsel teması aktarılmamış','Klinik giriş belirtisini doğrudan açıklamaz.'),('Eski toplantı arşivi yeniden indekslenmemiş','Uygulamaya kimlik doğrulamayı destekleyen bir bağımlılık değildir.'),('Yemekhane raporları ertesi güne bırakılmış','Verilen klinik erişim arızasının doğrudan nedeni değildir.'),'Kurtarma yalnız ana uygulamayı açmak değildir. Kimlik, ağ, DNS, veri ve dış hizmet gibi bağımlılıklar birlikte çalışmalıdır.','Uçtan uca gerçek kullanıcı işlemi olmadan uygulamayı kurtarılmış sayma.')
decision(4,'scenario','Yedek ve geri yükleme','Hastanede yedek işleri yeşil görünüyor. Tatbikatta dosya açılmadı; şifre çözme anahtarı bulunamadı. Cem (Operasyon Müdürü), “Yedek başarılı, testin önemi yok” diyor.','En uygun sonuç hangisi?',('Geri yükleme yeteneğinin kanıtlanmadığını raporlamak','Başarılı yazma kaydı kullanılabilir geri yükleme sonucuna eşit değildir.'),('Yeşil işler nedeniyle sürekliliği yeterli saymak','Kullanılamayan yedek işin kurtarmasını sağlamaz.'),('Yedekleme hiç çalışmadı diye kesin yazmak','Yazma işlemiyle geri yükleme başarısızlığı farklı olgulardır.'),('Anahtar bulunamadığı için bütün kanıtı silmek','Başarısızlık kanıtını korumak ve çözümlemek gerekir.'),'Yedek kontrolü, verinin geri okunabilirliğini ve gerekli anahtarları da kapsar. Bu vaka yedek işinin çalışmadığını değil, kurtarmanın doğrulanmadığını gösterir.','Anahtar erişimi ve geri yükleme adımlarını düzeltip tekrar test kanıtı al.')
decision(4,'choice','RTO ölçümü','Hastanenin kabul edilen RTO’su 2 saat. Kesinti 08.00’de başladı; sunucu 09.00’da açıldı, klinik hizmet 11.00’de kullanılabilir oldu.','Hedef karşılandı mı?',('Hayır; kullanılabilir klinik hizmet için üç saat geçti','Kurtarma hizmet düzeyinde ölçülür, yalnız sunucu açılmasıyla bitmez.'),('Evet; sunucu bir saat içinde açıldığı için karşılandı','Bileşen başlangıcını kullanılabilir iş hizmetine eşitler.'),('Evet; yedek dosyasının zamanı yeterince günceldi','Yedek yaşı veri kaybını ilgilendirir; hizmet dönüş süresini değil.'),('Hayır; RTO hiçbir zaman saat cinsinden ölçülmez','RTO bir zaman hedefidir ve saat cinsinden ifade edilebilir.'),'Hedefin tanımına göre gerçek hizmet geri dönüşü esas alınır. Sunucu bir saatte açılmış olsa da klinik süreç üç saat sonra çalışmıştır.','Tatbikat raporunda bileşen açılışı ve iş hizmeti doğrulama saatini ayrı tut.')
multi(4,'SLA ölçütleri','Kuzey Rota dış taşıma API’si için SLA hazırlıyor. İş gereksinimi gece gönderilerin 06.00’ya kadar işlenmesi.','Uygun iki hizmet ölçütünü seç.',[('Gönderilerin belirlenen saate kadar işlenme oranı','Doğrudan iş sonucunu ve zaman sınırını ölçer.'),('Başarısız aktarımın bildirim ve çözüm süreleri','İstisna yönetimini ölçülebilir kılar.'),('Satıcının kullandığı sunucu markasının popülerliği','İş hizmeti sonucunu ölçmez.'),('Satıcının sunumundaki memnuniyet sıfatları','Ölçülebilir hedef ve veri tanımı değildir.')],'SLA ölçütü iş ihtiyacına, veri kaynağına ve ölçüm yöntemine bağlanmalıdır. Satıcının teknik itibarı hizmet taahhüdünün yerine geçmez.','Ölçütün nasıl hesaplanacağını ve kim tarafından doğrulanacağını sözleşmede netleştir.')
order(4,'DR tatbikatı','Kuzey Rota yedek merkeze geçiş tatbikatı yapacak. Taslak senaryo hazır ama onay ve başarı ölçütleri yok.',['Kapsam, güvenlik sınırları ve başarı ölçütlerini onaylat','Gerekli ekip ve bağımlılıklarla tatbikatı yürüt','Süre, veri bütünlüğü ve iş işlemlerini ölç','Sapmaları aksiyonlara bağlayıp tekrar test planla'],'Tatbikatın anlamı ölçülebilir hedefle oluşur. Güvenlik sınırları iş kesintisi yaratmayı kontrol eder; sonuçlar yalnız “test yapıldı” olarak kapatılmaz.','Test başında neyin başarı sayılacağını yaz; sonuç sonrası hedefi değiştirerek başarılı gösterme.')
decision(4,'drag_select','Bağımsız yedek','Kuzey Rotanın fidye yazılımı senaryosunda üretim yöneticisi hesabı ele geçirilmiş varsayılıyor.','Hangi yedek düzeni bu tehdide daha dayanıklı?',('Ayrı yetkili, değiştirilemez yedek kopyası ve geri yükleme testi','Üretim hesabının yedekleri bozmasını sınırlar ve kullanılabilirliği doğrular.'),('Üretim hesabıyla silinebilen aynı depoda kopya','Aynı ele geçirilmiş yetki her iki kopyayı etkileyebilir.'),('Aynı açık ağ klasörüne daha sık dosya kopyalama','Sıklık erişim ve silinme riskini tek başına azaltmaz.'),('Yalnız RAID kullanıp bağımsız kopyayı kaldırma','Disk dayanıklılığı kötü niyetli değişiklik veya silmeyi çözmez.'),'Kopya sayısı kadar bağımsızlık ve erişim önemlidir. RAID hizmet dayanıklılığı sağlayabilir; veri silinmesine karşı bağımsız yedek değildir.','Tehdit senaryosunda saldırganın hangi kopyaya hangi hesapla ulaşabileceğini test et.')
fill(4,'Kesinti hedefi','Kuzey Rotanın iş sahibi, sipariş hizmetinin en geç dört saatte geri gelmesini kabul ediyor. Veri kaybı için ayrı bir hedef var.','Hizmetin geri gelme süresi hedefinin kısaltması nedir?',['RTO'],'RTO hizmeti geri döndürme hedefidir. Veri kaybı toleransı RPO’dur; birinin karşılanması diğerinin karşılandığını göstermez.','Hem süreyi hem veri kaybını bağımsız ölç; tek bir “DR başarılı” kutusuna indirgeme.')
decision(4,'scenario','Acil değişiklik','Aras Veri Merkezinde kesintiyi gidermek için acil ayar değişti. Yetkili acil onay kaydı var; test ve sonraki inceleme normalden kısaltılmış.','Denetçinin uygun yaklaşımı hangisi?',('Acil yetki, kayıt ve sonradan inceleme kanıtını test etmek','Acil akışta farklı kontrol olabilir; tamamen kontrolsüz olması gerekmez.'),('Acil değişiklik olduğu için bütün kayıtları gereksiz saymak','Acil durum izlenebilirlik ve uygun yetki ihtiyacını kaldırmaz.'),('Normal akıştan farklı diye otomatik usulsüzlük ilan etmek','Onaylı acil süreç ve koşullar ayrıca değerlendirilmelidir.'),('Kesinti bittiği için değişikliği hiç incelememek','Hizmet dönmesi değişiklik riskinin tamamen giderildiğini göstermez.'),'Acil değişiklik normal akışla aynı olmayabilir. Ancak yetki, gerekçe, kayıt ve sonraki doğrulama süreçte tanımlı ve uygulanmış olmalıdır.','Kontrolü işlemin gerçek aciliyeti ve kurumun acil akışı üzerinden değerlendir.')
decision(4,'choice','Veritabanı tutarlılığı','Duru E-ticarette sipariş toplamı ile ödeme toplamı farklı. DBA, “Veritabanı çalışıyor, kontrol tamam” diyor.','Hangi çalışma uygundur?',('İş kuralına göre veri bütünlüğü ve mutabakat testleri','Hizmetin açık olması iş verisinin doğru olduğunu kanıtlamaz.'),('Yalnız bağlantı kurulabildiğini tekrar göstermek','Bağlantı testi veri anlamı ve toplam doğruluğunu değerlendirmez.'),('Veritabanı sürümünü yükseltip farkı kapatmak','Neden anlaşılmadan teknik değişiklik veri sorununu çözmez.'),('Farkı silerek iki raporu aynı tutara getirmek','Kanıtsız veri düzeltme hatayı gizler ve bütünlüğü bozar.'),'Kullanılabilirlik ile bütünlük farklı kontrol amaçlarıdır. Sipariş ve ödeme farkı, geçerli iş kuralları ve işlem durumlarıyla açıklanmalıdır.','Bekleyen, iptal edilen ve iade edilen kayıtları uygun mutabakat kapsamına dahil et.')
order(4,'Tekrarlanan restore testi','Hastanedeki anahtar sorunu çözüldü. Önceki başarısız tatbikatın bulgusu açık. Henüz yeni test yapılmadı.',['Yeni anahtarla kontrollü geri yükleme yap','Kritik klinik işlemler ve veri bütünlüğünü doğrula','Ölçülen sonuçları RTO ve RPO hedefleriyle karşılaştır','Yeterli kanıtla bulgu durumunu güncelle'],'Bir çözümün kurulduğunu görmek yeterli değildir. Yeniden test kullanılabilir hizmeti, veri doğruluğunu ve hedef süreleri birlikte doğrulamalıdır.','Önceki testin başarısız koşulunu yeni testte tekrar kapsadığından emin ol.')
decision(4,'drag_select','İş sürekliliği önceliği','Hastanenin tatbikatında aynı anda dört olay bildirildi. İnsan güvenliği öncelikli.','İlk hangisi ele alınmalı?',('Elektrik panosunda duman ve personel tehlikesi','İnsan güvenliği teknoloji kurtarmasından önce gelir.'),('Rapor sunucusunun geri dönüşü gecikti','Hizmet kaybı önemlidir; mevcut fiziksel tehlikeden önce gelmez.'),('Eğitim portalında tema yüklenemedi','Verilen koşulda düşük iş etkili bir hizmet sorunudur.'),('Arşiv aktarımının tamamlanması uzadı','Bu gecikme mevcut insan güvenliği riskini öncelik dışı yapmaz.'),'Süreklilik planı insanları korumayı ihmal edemez. Fiziksel tehlikede güvenli tahliye ve yetkili acil müdahale, sistem geri dönüşünün önüne geçer.','Denetim tatbikatında güvenlik sınırlarını gerçek bir tehlike oluşursa uygulanacak şekilde belirle.')
decision(4,'scenario','Dayanıklılık raporu','Domain 4 sonu. Sunucular kurtarıldı fakat klinik giriş gecikmesi RTO’yu aştı. Yönetim rapora “Tüm hedefler sağlandı” yazılmasını istiyor.','En uygun rapor nedir?',('Başarılı adımları ve hedef sapmasını ayrı göstermek','Gerçek kazanımı ve kalan iş riskini birlikte açıklar.'),('Sunucular açıldığı için tüm hedefleri sağlandı saymak','Hizmet düzeyindeki ölçülen başarısızlığı gizler.'),('Tek sapma nedeniyle bütün test kanıtını geçersiz saymak','Geçerli olumlu kanıtlar da doğru kapsamda korunmalıdır.'),('Hedefi testten sonra üç saate çıkarıp başarı yazmak','Sonradan hedef değiştirerek test sonucunu çarpıtır.'),'Dayanıklılık raporu bileşen başarısını iş hedefi başarısından ayırır. Sapma için sahip, aksiyon ve yeniden test planı gerekir.','Hedef değişikliği gerekirse iş sahibi ayrı kararla onaylar; geçmiş test sonucu yine kendi hedefiyle raporlanır.')
# DOMAIN 5 — Integrate technical evidence with responsible incident decisions.
decision(5,'choice','Bilgi sınıflandırma','Kıyı Bankasında müşteri hesap dökümü herkese açık dosya alanına konmuş. Ayşe (Veri Sahibi), “Teknik ekip sınıfını seçer” diyor.','En uygun yaklaşım hangisi?',('İş veri sahibinin sınıflandırma kararını netleştirmek','İş bağlamına ve gereksinime göre sınıfı yetkili veri sahibi belirler.'),('Dosyanın boyutuna göre gizlilik sınıfı atamak','Dosya büyüklüğü veri hassasiyetini göstermez.'),('Depolama ucuzsa veriyi açık alanda tutmak','Maliyet erişimin uygunluğunu belirlemez.'),('Denetim adına tüm veri sınıflarını tek başına değiştirmek','Denetçi yönetimin veri sahipliği rolünü üstlenmez.'),'Sınıflandırma verinin hassasiyeti ve iş önemine göre koruma ihtiyacını belirler. Teknik ekip uygulamayı yönetebilir; iş kararının sahibi ayrı olmalıdır.','Hassas veriyi, sahip ve erişim kuralıyla eşleştir; tanımsız sınıfı sessizce varsayma.')
multi(5,'Erişim eşleştirme','Bankada erişim incelemesi yapıyorsun. Kimlik doğrulama ve yetkilendirme sık karıştırılıyor.','Doğru iki eşleştirmeyi seç.',[('Kimlik doğrulama → kullanıcının kimliğini sınama','Kimliğin iddiasını doğrular.'),('Yetkilendirme → kullanıcının yapabileceği işlemi belirleme','Doğrulanmış kimliğin izin kapsamını belirler.'),('Şifreleme → kullanıcının tüm iş rollerini onaylama','Şifreleme rol ve işlem yetkisi kararı değildir.'),('Yedekleme → kullanıcının kimliğini doğrulama','Yedekleme kimlik doğrulama işlevi görmez.')],'Başarılı giriş, her işleme yetki anlamına gelmez. Kimlik doğrulama ve izin denetimi ayrı katmanlardır; her biri kendi riski için test edilir.','MFA var diye geniş yetkileri uygun sayma; rol ve işlem sınırlarını ayrıca incele.')
order(5,'Ayrılan çalışan erişimi','Bankada HR 18.00’de ayrılış kaydını tamamladı. Onaylı süreç aynı gün kapatma gerektiriyor. Güvenlik ekibinin uygulama akışını sırala.',['HR ayrılış bildirimi ve çalışan kimliğini doğrula','İlgili hesap ve aktif oturumları belirle','Yetkili süreçle hesapları ve oturumları kapat','Kapanış zamanını ve sistem sonuçlarını doğrula'],'Kapanacak kimlik ve sistem kapsamı doğrulanmadan işlem yapmak yanlış hesabı etkileyebilir. Sadece dizin hesabı değil ilgili oturum ve uygulamalar da kapsamda olmalıdır.','HR kaydıyla teknik kapanış kanıtını aynı çalışan ve zaman çizelgesinde eşleştir.')
decision(5,'drag_select','Ayrıcalıklı erişim','Dört erişim kaydı var. Amacın en önemli ayrıcalık ve izlenebilirlik açığını bulmak.','Hangisi öncelikli?',('Ortak yönetici hesabı; kim kullandı bilinmiyor, geniş yetki var','Yüksek yetki ve kişi izlenebilirliği eksikliği birlikte risk oluşturur.'),('Bireysel okuma hesabı; iş sahibi onayı var','Verilen kayıt sınırlı yetki ve onay içeriyor.'),('Geçici test hesabı; süre sonunda kapanmış','Süreli erişim kapanışı uygulanmış görünüyor.'),('Yeni çalışan hesabı; rol matrisiyle uyumlu','Verilen koşulda tanımlı iş ihtiyacına uygun erişim var.'),'Ayrıcalıklı hesapta hem yetkinin sınırı hem işlemin kime ait olduğu önemlidir. Ortak kimlik sorumluluğu ve olay incelemesini zayıflatır.','Bireysel erişim, onay, süre ve kayıt kontrollerini beraber değerlendir.')
fill(5,'En az ayrıcalık','Bir çağrı merkezi çalışanı yalnız kendi müşterilerinin kayıtlarını okumalı. Tüm kayıtları dışarı aktarma yetkisi görev için gerekmiyor.','Yalnız gerekli yetkinin verilmesi hangi ilkedir?',['en az ayrıcalık','minimum yetki','en az yetki','least privilege'],'En az ayrıcalık, işi yapmak için gereken izinlerle erişimi sınırlar. Kullanıcıya güvenmek gereksiz dışa aktarma yetkisini uygun hale getirmez.','Rol matrisiyle gerçek yetkileri karşılaştır; sadece hesap sahibinin aktif olduğunu kontrol etme.')
decision(5,'scenario','Ağ segmentasyonu','Ufuk Sağlığın ziyaretçi Wi-Fi ağı klinik veri sunucusuna erişebiliyor. Deniz (CISO), “Wi-Fi parolası güçlü” diyor.','En uygun öneri hangisi?',('Ziyaretçi ağının klinik ağa erişimini gereksinimle sınırlamak','Güçlü parola ağlar arası gereksiz erişimi engellemez.'),('Wi-Fi parolasını uzatıp ağ geçişini açık bırakmak','Kimlik bilgisi gücü segmentasyon açığını çözmez.'),('Klinik sunucu adını gizleyip bağlantıyı korumak','Adresin gizlenmesi erişim kontrolü değildir.'),('Günlük rapora yalnız bağlanan kişi sayısını eklemek','Sayı ölçümü izin verilen ağ yolunu sınırlandırmaz.'),'Ağ segmentasyonu gereksiz erişim yollarını azaltır. Yetkili ziyaretçi bağlantısı bile klinik sisteme erişim hakkı yaratmaz.','Kuralı belgede görmekle yetinme; izin verilen ve reddedilen yolları kontrollü test et.')
decision(5,'choice','Kriptografik anahtar','Hastanenin arşivi şifreli. Anahtar aynı sunucuda herkesin okuyabildiği dosyada duruyor.','En önemli kontrol odağı nedir?',('Anahtar erişimini ve yaşam döngüsünü korumak','Anahtar ele geçirilirse şifrelemenin gizlilik faydası zayıflar.'),('Şifreli dosyanın adını daha karmaşık yapmak','Dosya adı anahtarın açık erişimini düzeltmez.'),('Arşivi iki kez sıkıştırıp anahtarı aynı yerde tutmak','Sıkıştırma anahtar koruma kontrolü değildir.'),('Yalnız algoritma adını rapora ekleyip yeterli saymak','Algoritma adı hatalı anahtar yönetimini ortadan kaldırmaz.'),'Şifreleme doğru algoritmadan ibaret değildir. Anahtar oluşturma, erişim, saklama, değişim ve kurtarma süreci kontrolün parçasıdır.','“Şifreli” kutusunu işaretlemeden anahtarı kimlerin elde edebildiğini ve işlemlerin izini incele.')
order(5,'Sertifika yönetimi','Duru E-ticaretin üretim sertifikası ay sonunda bitecek. Yeni sertifika henüz talep edilmedi. Onaylı değişiklik sürecini izle.',['Sertifika envanteri, sahibi ve hizmet kapsamını doğrula','Yetkili süreçle yeni sertifikayı edin ve doğrula','Onaylı değişiklikle kurup istemci bağlantısını test et','Bitiş izleme ve kanıt kayıtlarını güncelle'],'Sertifika yenileme, yalnız bir dosya almak değildir. Doğru hizmet kimliği, güven zinciri ve gerçek bağlantı testleri gerekir.','Yenilemenin otomatik olması sahibin ve başarısızlık bildiriminin gereksiz olduğu anlamına gelmez.')
decision(5,'drag_select','Güvenlik izleme','Duru E-ticaretin SOC panelinde dört gösterge var. İzleme güvencesini en çok sorgulatanı seç.','Hangisi önce araştırılmalı?',('Ödeme sunucusundan altı saattir güvenlik logu gelmiyor','Kritik sistem için gözlem boşluğu oluşmuştur.'),('Eğitim sisteminde alarm sayısı önceki güne eşit','Alarm sayısı tek başına bir boşluk kanıtı değildir.'),('Bir düşük riskli alarm triage sonucu kapatılmış','İncelenmiş kapatma tek başına izleme arızası değildir.'),('Panelde renk paleti yeni standarda geçirilmiş','Görsel değişim veri gelmemesi kadar önemli değildir.'),'Sıfır alarm her zaman güvenlik demek değildir; hiç veri gelmiyor da olabilir. Log kaynağı, iletim ve toplama sağlık kontrolleri ayrıca izlenmelidir.','Tehdit aramadan önce sistemi görebildiğinden emin ol.')
decision(5,'scenario','Farkındalık ölçümü','Duru E-ticarette çalışanların tamamı eğitimi açmış. Oltalama tatbikatında bildirim oranı düşük; kimlik bilgisi paylaşımı sürüyor.','En uygun değerlendirme nedir?',('Katılım ile davranış etkisini ayrı değerlendirmek','Eğitim açma kaydı öğrenilen davranışı kanıtlamaz.'),('Katılım yüzde yüz diye programı kesin etkili saymak','Faaliyet tamamlanmasını sonuçla karıştırır.'),('Hata yapan tüm çalışanları halka açık listelemek','Öğretici ve kontrollü değerlendirme yerine gereksiz ifşa yaratır.'),('Başarısız davranış ölçümlerini rapordan çıkarmak','Önemli sonuç kanıtını seçici biçimde gizler.'),'Farkındalık programının amacı güvenli davranış ve zamanında bildirimdir. Katılım gerekli bir faaliyet ölçüsü olabilir; etkiyi ayrıca sınamak gerekir.','Hata örüntülerini hedefli eğitim ve bildirim kolaylığına dönüştür; kişileri damgalama.')
decision(5,'choice','Bulut veri erişimi','Kuzey Rotanın bulut deposu internete açık. Deniz (CISO), “Dosyalar şifreli olduğu için sorun yok” diyor. Erişim iş ihtiyacı yok.','En uygun değerlendirme hangisi?',('Gereksiz açık erişimi ve anahtar kontrollerini birlikte incelemek','Şifreleme erişim ve yapılandırma kontrolünün yerine geçmez.'),('Şifreleme nedeniyle açık erişimi otomatik kabul etmek','Ek koruma diğer kontrol ihtiyacını kaldırmaz.'),('Dosya adını değiştirip açık erişimi yeterli saymak','Ad değişimi yetkisiz erişim yolunu kaldırmaz.'),('Sadece depolama maliyetini azaltmaya odaklanmak','Maliyet mevcut veri maruziyeti riskini ele almaz.'),'Katmanlı güvenlikte şifreleme, erişim sınırı ve anahtar yönetimi birbirini tamamlar. Hatalı yapılandırma yine bilgi maruziyeti ve kötü kullanım riski yaratır.','Depoyu farklı erişim rolleri ve dış bağlantı koşullarıyla, yetkili test kapsamında doğrula.')
multi(5,'Güvenlik olayı kanıtı','Kuzey Rotada şüpheli veri aktarımı var. Deniz (CISO) olay ekibini kurdu. Denetim, kanıtın korunmasını değerlendirecek.','Hangi iki uygulama uygun?',[('Kanıtın alım zamanı, kaynağı ve teslim zincirini kaydetmek','Kanıtın kim tarafından nasıl işlendiğini izlenebilir kılar.'),('Yetkili yöntemle kopya alıp bütünlüğünü doğrulamak','Analizin asıl kanıtı değiştirmeden yapılmasını destekler.'),('Şüpheli dosyaları incelemeden hemen yok etmek','İnceleme için gerekli kanıtı ortadan kaldırabilir.'),('Her çalışanla ham müşteri verisini paylaşmak','Olay gereksinimini aşan ifşa ve erişim riski yaratır.')],'Olay incelemesinde hız kadar kanıt bütünlüğü ve yetki önemlidir. Kaynak, zaman, yöntem ve teslim kaydı bulguların güvenilirliğini destekler.','Denetçi uygun olay ekibinin rolünü üstlenmeden kanıt koruma kontrolünü ve rapor dayanağını değerlendirir.')
order(5,'Güvenlik müdahalesi','Kuzey Rotada yetkisiz yönetici oturumu doğrulandı. İnsan güvenliği etkisi yok. Yetkili ekip onaylı playbook ile ilerleyecek; kanıt koruma her adımda sürüyor.',['Olay kapsamını ve yetkili müdahale kararını netleştir','Etkilenen erişimi kontrollü biçimde sınırla','Kök nedeni giderip temiz ortamı geri getir','Kurtarmayı doğrula ve alınan dersleri kaydet'],'Olayın kapsamına uygun sınırlama yapılır; kök neden giderilmeden yalnız hizmeti açmak yeniden olay riskini bırakır. Kanıt koruma ve iletişim bu adımlarla birlikte yürür.','Sıra, bu tanımlı playbook içindir; gerçek olayda güvenlik ve delil koşulları eşzamanlı karar gerektirebilir.')
decision(5,'drag_select','Güvenlik testi yetkisi','Kuzey Rota dört test önerisini değerlendiriyor. Üretim kesintisi yaratmadan yetkili güvenlik incelemesi hedefleniyor.','Hangi öneri önce düzeltilmeli?',('Kapsam ve izin olmadan üretimde sömürü testi başlatmak','İş etkisi, yetki ve güvenlik sınırları tanımlanmamıştır.'),('Onaylı kapsamda test ortamında doğrulama yapmak','Yetki ve ortam sınırı tanımlı bir yaklaşımdır.'),('Test zamanını iş sahibiyle önceden kararlaştırmak','İş etkisini kontrol etme amacına uygundur.'),('Kritik bulguları güvenli kanaldan bildirmek','Bulguların erişimini kontrol etmeye hizmet eder.'),'Güvenlik testi iyi niyetle bile zarar verebilir. Yetki, kapsam, zaman, veri işleme ve durdurma koşulları baştan tanımlanmalıdır.','Denetim yetkisini sınırsız saldırı izni gibi yorumlama.')
fill(5,'Veri sızıntısını önleme','Bankanın müşteri listesinin dış e-postaya gönderimini sınıflandırma kurallarıyla saptayan ve gerektiğinde engelleyen kontrolü inceliyorsun.','Bu kontrol ailesinin yaygın kısaltması nedir?',['DLP'],'DLP, belirlenmiş veri ve kullanım kurallarıyla sızıntı riskini azaltır. Kapsam, yanlış alarm ve gerçek engelleme sonucu test edilmeden aracın varlığı yeterli değildir.','Kuralın hangi veriyi hangi kanalda koruduğunu kanıtla; tüm kanalları kapsadığı varsayımından kaçın.')
decision(5,'scenario','Mobil cihaz güvenliği','Ufuk Sağlıkta kayıp tabletin içinde hasta kayıtları var. Uzaktan silme ayarı etkin; cihaz günlerdir ağa bağlanmamış.','En uygun sonuç hangisi?',('Silmenin gerçekleşmesini doğrulayıp kalan maruziyeti değerlendirmek','Silme ayarı ile fiilen tamamlanan silme farklıdır.'),('Uzaktan silme açık olduğu için tüm riski kapatmak','Bağlantı kurulmadan komut uygulanmamış olabilir.'),('Tablet kayıp olduğu için şifrelemeyi gereksiz saymak','Cihaz şifrelemesi yerel veri erişimini azaltabilir.'),('Kanıt olmadan hasta verisinin kesin sızdığını yazmak','Kayıp cihaz tek başına gerçekleşmiş sızıntı kanıtı değildir.'),'Uzaktan silme uygulanabilirliğe bağlıdır. Cihaz şifrelemesi, oturum kilidi ve veri miktarı da kalan riski etkiler. Olası maruziyet gerçekleşmiş sızıntıyla aynı değildir.','Olay kaydında komut, uygulama sonucu ve belirsizliği ayrı göster.')
decision(5,'choice','Fiziksel güvenlik','Aras Veri Merkezinde kart okuyucu kayıtları tam. Kamera örneklerinde çalışanla birlikte kartsız kişi geçiyor. Güvenlik sorumlusu “Kayıtlarda yabancı yok” diyor.','En uygun değerlendirme nedir?',('Kartsız takip girişini ve kapı kontrolünün etkinliğini incelemek','Kart kaydı tek başına gerçek geçen tüm kişileri göstermeyebilir.'),('Kayıtlarda görünmediği için kartsız girişi yok saymak','Gözlenen olay kanıtını kayıt eksikliğiyle çelişmeden çıkaramazsın.'),('Kart okuyucu var diye fiziksel kontrolü yeterli saymak','Kontrolün kurulması etkin işletildiği anlamına gelmez.'),('Bütün ziyaretçileri kanıtsız biçimde saldırgan ilan etmek','Yetkisiz veya kayıtsız giriş niyetin kanıtı değildir.'),'Fiziksel kontrolün amacı gerçek erişimi sınırlandırmaktır. Cihaz kaydıyla gözlemi karşılaştırmak takip girişleri gibi kontrolün atlanabildiği yolları gösterir.','Giriş politikası, ziyaretçi eşliği ve uygulama kanıtını birlikte test et.')
order(5,'Güvenlik bulgusu takibi','Ziyaretçi Wi-Fi ile klinik ağ arasına yeni kural kondu. Yönetim bulgunun kapandığını söylüyor; denetim henüz kontrolü sınamadı.',['Onaylı ağ gereksinimi ve yeni kuralı karşılaştır','Yetkili kapsamda yasak erişim yolunu yeniden test et','Gerekli klinik bağlantıların çalıştığını doğrula','Test kanıtıyla kalan risk ve kapanış kararını kaydet'],'Çözüm hem istenmeyen erişimi engellemeli hem gerekli hizmeti korumalıdır. Kural ekran görüntüsü tek başına etkinlik ve yan etki testinin yerine geçmez.','Kontrol değiştiğinde olumlu ve olumsuz erişim testlerini birlikte düşün.')
decision(5,'drag_select','Bütünleşik risk kararı','Final toplantısı için üç kurumdan dört bulgu geldi. Hangisi hemen yetkili güvenlik ve iş sahibine taşınmalı?','En acil riski seç.',('Bankada aktif saldırı ve doğrulanmış yetkisiz müşteri aktarımı','Devam eden ve doğrulanan veri kaybı için hızlı yetkili müdahale gerekir.'),('Belediyede eğitim sunumunun bir sayfası eski','Verilen koşulda devam eden kritik olay göstermiyor.'),('Veri merkezinde bir envanter etiketi silik','Etiket sorunu aktif veri aktarımı kadar acil değildir.'),('Sigortada kapanış toplantısının daveti gecikmiş','İdari gecikme mevcut kritik olayla aynı etkiye sahip değildir.'),'Aktif ve doğrulanmış olay, rutin rapor döngüsünü beklemeyebilir. Denetim bulguyu uygun kanaldan hızla bildirir; yetkili müdahale ekibi olayı yönetir.','Aciliyeti kanıt, süreklilik ve iş etkisiyle gerekçelendir; kendi yetkin dışında müdahale başlatma.')
decision(5,'scenario','Mesleki değerlendirme','100. kararın. Ayşe (Komite Başkanı), “Bir hastanede RTO aşıldı, bankada yetkisiz aktarım var. Bizi rahatlatacak tek cümle söyle” diyor. Kontrollerin bazıları çalışıyor; iki risk için aksiyon ve doğrulama sürüyor.','En uygun kapanış yaklaşımı nedir?',('Kanıtlı durumu, açık riskleri ve gereken kararları net sunmak','Bağımsız güvence, hem başarıyı hem açık riski ve karar ihtiyacını dürüstçe anlatır.'),('Rahatlatmak için bütün kontrollerin yeterli olduğunu söylemek','Bilinen açık riskleri gizleyerek güvenceyi çarpıtır.'),('İki bulgu nedeniyle tüm kurumları başarısız ilan etmek','Bulguların kapsamını bütün kuruma kanıtsız genişletir.'),('Kurul yerine risk kabulünü denetim adına yapmak','Risk kararının sahibi yetkili yönetimdir, denetçi değildir.'),'İyi denetçi belirsizliği saklamaz; kanıtı ve iş etkisini anlaşılır karar bilgisine dönüştürür. İşin özü bütün cevapları ezberlemek değil, kanıtın sınırını bilerek doğru soruyu sormaktır.','Bu vakalarda en çok hangi işi sevdin: analiz, teknik kontrol, risk tartışması veya iletişim? Sonuçların mesleğe uygunluk hükmü değildir; ilgi ve gelişim alanlarını keşfetmek için başlangıçtır.')

